const coinRoutes=new Map();
const publicRoute=()=>decodeURIComponent(location.hash.slice(1)||location.pathname.replace(/^\/+|\/+$/g,'')||'home');
const route=()=>{const r=publicRoute();return coinRoutes.get(r)||r};
const routePath=r=>r==='home'?'/':'/'+r.replace(/^#?\/?/,'');
function rememberCoinRoute(c){if(!c.mint)return;const logical=(c.onepill||c.phase==='onepill'?'onepill/':'coin/')+c.id;coinRoutes.set('coin/'+c.mint,logical);const current=publicRoute();if(current===logical||current==='coin/'+c.id||current==='coin/'+c.mint)history.replaceState(history.state,'',routePath('coin/'+c.mint));}
function navigate(r){const path=routePath(r);if(location.pathname+location.hash===path)return;history.pushState(null,'',path);window.dispatchEvent(new HashChangeEvent('hashchange'));}
if(location.hash)history.replaceState(history.state,'',routePath(publicRoute()));
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target||a.hasAttribute('download'))return;const raw=a.getAttribute('href');if(!/^#(home|coin\/|onepill\/|profile\/|launch|raids|stats|about|status|docs)/.test(raw)&&!/^\/(coin|onepill|profile)\//.test(raw))return;event.preventDefault();navigate(raw.replace(/^#/,'').replace(/^\//,''));});
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function showDialog(title,body){modal.innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2><button class="subtle iconbutton" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;modal.showModal()}
function errorText(error){const messages={onepill_metadata_unavailable:'The IPFS metadata could not be read. Check that it is pinned and publicly available.',onepill_metadata_name_mismatch:'The name and ticker must match your IPFS metadata document.',onepill_ipfs_metadata_required:'Use a published ipfs:// metadata JSON link for OnePill.',onepill_payment_already_started:'A payment is already being checked. Open My OnePill launches to resume; do not pay twice.',onepill_invalid_ownership_proof:'The ownership signature could not be verified. Reconnect the wallets used for this quote.',onepill_invalid_quote:'Pangea returned unexpected launch terms. No payment was requested.',onepill_invalid_payment:'Pangea returned an unexpected payment. Nothing was sent.',onepill_quote_rate_limit:'Please wait before requesting more OnePill quotes.',insufficient_balance:'This connected wallet does not hold enough of this coin. Switch to the wallet that bought it.',insufficient_tokens:'This connected wallet does not hold enough tokens to sell.',buy_slot_limit:'Launch protection: all wallets share a 1% supply limit per slot. Reduce your buy or request a fresh quote next slot.',developer_buy_slot_limit:'The initial developer buy must fit within 1% of supply. Reduce the amount.',launch_payments_disabled:'Launch payments are not enabled yet.',trading_not_configured:'Trading is not enabled yet.',unauthenticated:'Please reconnect your wallet to sign in.',x_not_configured:'X verification is not configured yet.',price_provider_not_configured:'The price feed is not connected yet.',rate_limited:'Too many requests. Please wait a minute.',request_already_created:'This launch was already requested. Recover its saved status before trying again.'};return messages[error.message]??error.message.replace(/_/g,' ')}
function walletName(address){queueWalletProfiles();return walletNames.get(address)||String(address||'').slice(0,6)||'unknown'}
function walletBadge(address,dev=false){let hash=0;for(const char of String(address).slice(0,6))hash=(char.charCodeAt(0)+((hash<<5)-hash))|0;hash=Math.abs(hash);const color='#'+[hash%128+127,(hash>>8)%128+127,(hash>>16)%128+127].map(n=>n.toString(16).padStart(2,'0')).join('');return `<a class="wallet-badge" href="#profile/${e(address)}" title="${e(address)}" style="--wallet-color:${color}">${walletAvatar(address)}<span data-wallet-name="${e(address)}" data-wallet-dev="${dev}">${e(walletName(address))}${dev?' (dev)':''}</span></a>`}
function headerActivityMarkup(){const trades=headerActivity.filter(item=>item.type!=='launch'),launches=headerActivity.filter(item=>item.type==='launch'),trade=trades[headerActivityIndex%Math.max(1,trades.length)],launch=launches[headerActivityIndex%Math.max(1,launches.length)];const chip=item=>item?`<span class="signal ${item.type==='launch'?'signal-blue':item.type==='sell'?'signal-red':'signal-green'}" title="${item.time?e(new Date(item.time*1000).toLocaleString()):'Finalized slot '+item.slot}">${walletBadge(item.wallet)} <a href="#coin/${e(item.launch)}">${item.type==='launch'?'created':item.type==='buy'?'bought':'sold'} ${item.type==='launch'?'':(Number(item.quoteLamports)/1e9).toFixed(4)+' SOL of '}${e(item.symbol||item.name||short(item.mint))}</a>${item.image?`<img src="${art(item)}" alt="" width="16" height="16">`:''}${item.type==='launch'&&item.time?`<span>on ${e(new Date(item.time*1000).toLocaleDateString('en-US',{year:'2-digit',month:'2-digit',day:'2-digit'}))}</span>`:''}</span>`:'';return headerActivity.length?chip(trade)+chip(launch):`<span class="signal signal-muted">${headerFeedFailed?'Activity temporarily unavailable':'Waiting for launches and trades'}</span>`}
async function loadHeaderActivity(){if(headerFeedPending||preview||document.hidden)return;headerFeedPending=true;try{const data=await api.request('/coins/activity-feed?limit=50');const previous=headerActivity[0]?.signature;headerActivity=data.items??[];for(const item of headerActivity)if(item.username&&!walletProfileTimes.has(item.wallet))walletNames.set(item.wallet,item.username);if(previous!==headerActivity[0]?.signature)headerActivityIndex=0;headerFeedFailed=false}catch{headerFeedFailed=true}finally{headerFeedPending=false;paintHeaderActivity()}}
function paintHeaderActivity(rotate=false){const el=document.querySelector('#live-activity');if(!el||document.hidden||el.contains(document.activeElement)||el.matches(':hover'))return;if(rotate)headerActivityIndex++;const markup=headerActivityMarkup();if(el.dataset.markup===markup)return;el.dataset.markup=markup;el.innerHTML=markup;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{opacity:.65},{opacity:1}],{duration:180,easing:'ease-out'});}
function shell(content){const r=route().split('/')[0];document.body.classList.add('classic');document.body.classList.toggle('coin-view',r==='coin'||r==='onepill');document.body.classList.remove('light');document.body.classList.toggle('no-board-motion',!boardAnimations);app.innerHTML=`<header class="classic-header"><a class="classic-brand" href="#home" aria-label="Pill V1 home"><img src="/assets/pill-v1.svg" alt="Pill V1 gold-ring capsule"><span>Pill V1</span></a><nav aria-label="Main"><span><a href="#home">[board]</a><a href="#about">[our mission]</a></span><span><a href="#about/rules">[how it works]</a><a href="#raids">[raids]</a></span><span><span class="official-token-placeholder" role="link" aria-disabled="true" title="Official token link will be available after launch">[official platform token]</span></span></nav><div class="classic-signals" id="live-activity" aria-label="Recent on-chain activity">${headerActivityMarkup()}</div>${wallet?`<div class="classic-account"><details class="classic-account-menu"><summary title="${e(wallet)}">${walletAvatar(wallet)}<span data-wallet-name="${e(wallet)}">${e(walletName(wallet))}</span><span aria-hidden="true">▾</span></summary><div class="classic-account-options"><button data-action="copy" data-value="${e(wallet)}">Copy address</button><button data-action="disconnect">Disconnect</button></div></details><a class="classic-view-profile" href="#profile/${e(wallet)}">[view profile]</a></div>`:'<button class="classic-wallet" data-action="wallet">[connect wallet]</button>'}</header><main id="main" class="${r==='home'?'classic-board':'classic-page'}">${r!=='home'?'<a class="classic-back" href="#home">[go back]</a>':''}${content}</main><footer class="classic-footer"><span>Pill V1 · old is gold</span><div><a href="#about">[our mission]</a><a href="#stats">[stats]</a><a href="#docs">[docs]</a><a href="https://x.com/PillV1dotfun" target="_blank" rel="noopener noreferrer" aria-label="Pill V1 official X account">[X]</a><button data-action="risks">[terms & risks]</button></div><small>Independent launchpad. Not affiliated with pump.fun.</small></footer>`;bindForms();bindBoard() }
function art(c){if(c.onepill&&typeof c.image==='string'&&/^https:\/\//.test(c.image))return e(c.image);return c.example?artwork(c.art):c.image&&/^\/media\/[a-f0-9]{64}\.webp$/.test(c.image)?c.image:'/assets/pill-v1.svg'}
const verifiedLabelRules=new Map();
let labelHydrationBusy=false;
function tags(c){if(c.onepill)return '<div class="tags"><span class="tag onepill-tag">onepill mode</span><span class="tag">5 chains</span><span class="tag" title="Ethereum · Base · BNB Chain · Robinhood Chain · Solana">ETH · BASE · BNB · ROBINHOOD · SOL</span></div>';const r=c.launchRules||verifiedLabelRules.get(c.mint)?.rules;return `<div class="tags coin-feature-tags" data-rules-mint="${e(c.mint||'')}">${launchLabels(c.version,r).map(label=>`<span class="tag"${label.includes('max wallet')?' title="Maximum total token holding per wallet on the bonding curve; the separate shared buy limit is 1% of supply per slot."':''}>${e(label)}</span>`).join('')}</div>`}
async function hydrateCoinLabels(){
 if(labelHydrationBusy||preview)return;labelHydrationBusy=true;
 const pending=coins.filter(c=>c.version===11&&(!verifiedLabelRules.has(c.mint)||Date.now()-verifiedLabelRules.get(c.mint).at>60000));
 try{await Promise.all(Array.from({length:Math.min(4,pending.length)},async()=>{while(pending.length){const c=pending.shift();try{const rules=await api.launchRules(c.mint);if(rules.commitment!=='finalized')continue;verifiedLabelRules.set(c.mint,{rules,at:Date.now()});if(verifiedLabelRules.size>500)verifiedLabelRules.delete(verifiedLabelRules.keys().next().value);c.launchRules=rules;for(const el of document.querySelectorAll('[data-rules-mint]'))if(el.dataset.rulesMint===c.mint)el.outerHTML=tags(c)}catch{/* Do not invent settings when the chain read is unavailable. */}}}))}finally{labelHydrationBusy=false}
}
function launchRulesPanel(c){return `<section class="panel" id="coin-launch-rules"><h2>Launch rules</h2>${tags(c)}${c.launchRules?.buySlotCapBps===100?'<p class="note">Launch protection: all wallets combined can buy up to 1% of supply per slot before graduation. Selling does not reset the allowance. This limits concentrated buying; it does not identify every bundle.</p>':''}<p class="note">${c.launchRules?'Confirmed on chain. '+(c.launchRules.graduated?'Graduated: native PumpSwap fees apply.':'These settings apply on the bonding curve. Graduation setup comes from curve funds, capped at 0.05 SOL. Unused funds enter liquidity.'):'Loading confirmed launch settings…'}</p></section>`}
function coinRaidForm(c){if(c.launchRules?.feeMode!=='yap')return '';return `<section class="panel stack" id="coin-raid-form"><h3>Raid ${e(c.symbol||c.name)}</h3><p class="note">Link your X account and submit your post about this coin. Verified eligible holders share this coin’s available raider rewards.</p><button data-action="link-x">Link your X account</button><label class="field"><span>Your X post URL</span><input id="coin-raid-url" placeholder="https://x.com/you/status/…"></label><button class="primary" data-action="coin-submit-raid">Submit for verification</button><p class="note">Verification and the funded reward round determine eligibility and payment.</p></section>`}
async function loadLaunchRules(c,epoch){try{const rules=await api.launchRules(c.mint);if(epoch!==routeEpoch)return;c.launchRules=rules;verifiedLabelRules.set(c.mint,{rules,at:Date.now()});for(const labelEl of document.querySelectorAll('[data-rules-mint]'))if(labelEl.dataset.rulesMint===c.mint)labelEl.outerHTML=tags(c);if(rules.curve){const q=rules.curve;document.querySelector('#curve-percent').textContent=(Math.min(10000,q.progressBps)/100).toFixed(2)+'%';if(q.marketCapLamports){c.capSol=Number(q.marketCapLamports)/1e9;c.graduationCapSol=Number(q.estimatedGraduationMarketCapLamports)/1e9;updateDollarCap(c)}document.querySelector('#curve-detail').innerHTML=rules.graduated?'<h2>Bonding curve progress: 100%</h2><progress max="10000" value="10000" aria-label="Migration progress" style="width:100%;accent-color:#a4f5c4;margin:12px 0"></progress><p class="note">Liquidity migrated to PumpSwap.</p>':`<h2>Bonding curve progress: ${(Math.max(0,Math.min(10000,q.progressBps))/100).toFixed(2)}%</h2><progress aria-label="Migration progress" max="10000" value="${q.progressBps}" style="width:100%;accent-color:#a4f5c4;margin:12px 0"></progress><p class="note">${rules.curveComplete?'Curve complete. Waiting for migration to PumpSwap.<br>':''}${formatUnits(q.remainingTokensRaw,6,0)} tokens still available for sale.<br>${formatUnits(q.reserveLamports,9,4)} SOL in the bonding curve.<br>Estimated market cap at graduation: <span id="graduation-market-cap">${dollarQuote?.expiresAt>Date.now()?compactUsd(Number(q.estimatedGraduationMarketCapLamports)/1e9*dollarQuote.price):'—'}</span>.</p>`}const el=document.querySelector('#coin-launch-rules');if(el)el.outerHTML=launchRulesPanel(c);if(detailTab==='raids'&&!document.querySelector('#coin-raid-form'))document.querySelector('#detail-data')?.insertAdjacentHTML('beforeend',coinRaidForm(c));}catch{if(epoch===routeEpoch){const el=document.querySelector('#curve-detail');if(el&&!el.querySelector('progress'))el.innerHTML='<h2>Bonding curve progress</h2><p class="note">Progress temporarily unavailable. Retrying…</p>';}}}

function coinLinks(c){return ['twitter','telegram','website'].filter(k=>{try{const u=new URL(c[k]);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}).map(k=>`<a href="${e(c[k])}" target="_blank" rel="noopener noreferrer">[${k}]</a>`).join(' ')}
function crownBadge(c){return c.kingOfTheHill?.qualified?'<span class="crown-badge" title="Previously crowned King of the Hill" aria-label="Crowned King of the Hill">👑</span>':''}
function crownPanel(c){const k=c.kingOfTheHill;if(k?.qualified){const stamp=k.crownedAt==null?null:new Date(k.crownedAt*1000);return `<div class="crown-record">👑 Crowned king of the hill${stamp?` on <time datetime="${stamp.toISOString()}">${e(stamp.toLocaleString())}</time>`:` · slot ${e(k.crownedSlot)}`}</div>`}const progress=k?.progressBps;return `<div class="crown-progress"><div>king of the hill progress: ${progress==null?'—':Math.floor(progress/100)+'%'}</div><progress max="10000" value="${progress??0}" aria-label="King of the Hill progress"></progress><small>${c.onepill?'Reach 45 SOL held in the Solana pool to earn the crown.':'Dethrone the current king when 85% of the bonding-curve sale allocation is sold.'}</small></div>`}
function coinCard(c){const name=c.name||short(c.mint),ticker=c.symbol||short(c.mint);return `<article class="coin-card classic-coin ${bumpedCoins.has(c.id)?'coin-bumped':''}" data-coin="${e(c.id)}"><a class="coin-image" href="/coin/${e(c.mint||c.id)}" tabindex="-1" aria-hidden="true"><img class="art" src="${art(c)}" alt="" loading="lazy"></a><div class="coin-copy"><div class="author">created by ${walletBadge(c.creator)}</div>${tags(c)}<div class="classic-cap">market cap: ${Number(c.cap)>0&&dollarQuote?.expiresAt>Date.now()?compactUsd(Number(c.cap)*dollarQuote.price):'—'}</div><div class="classic-replies">replies: ${Number.isInteger(c.replyCount)?c.replyCount:'—'}</div><p><a href="/coin/${e(c.mint||c.id)}"><strong>${crownBadge(c)} ${e(name)} (ticker: ${e(ticker)}):</strong> ${e(c.description||'')}</a></p>${c.phase==='pumpswap'?'<span class="classic-bonded">graduated to PumpSwap</span>':''}</div><button class="favorite ${favorites.has(c.id)?'on':''}" data-action="favorite" data-id="${e(c.id)}" aria-label="${favorites.has(c.id)?'Remove from':'Add to'} watchlist: ${e(name)}" aria-pressed="${favorites.has(c.id)}">${icon('star')}</button></article>`}
function empty(title,text,action=''){return `<div class="empty">${icon('grid')}<h3>${e(title)}</h3><p>${e(text)}</p>${action}</div>`}
function filtered(){let list=coins.filter(c=>!query||[c.name,c.symbol,c.mint].some(x=>(x||'').toLowerCase().includes(query.toLowerCase())));if(sort==='watchlist')list=list.filter(c=>favorites.has(c.id));if(filter!=='all')list=list.filter(c=>filter==='curve'?(c.phase==='curve'||c.onepill):filter==='bonded'?c.phase==='pumpswap':filter==='near'?(c.progress>=50&&c.phase!=='pumpswap'):filter==='quick'?c.quick:filter==='blocked'?c.blocked:c.mode===filter);const metric=c=>sort==='cap'?Number(c.cap||0):sort==='new'?Number(c.created_slot||0):Number(c.bumpSlot||c.created_slot||0);return [...list].sort((a,b)=>(boardOrder==='asc'?1:-1)*(metric(a)-metric(b)))}
function home(){const king=kingOfTheHill;return `<section class="classic-start"><a href="#launch">[start a new coin]</a><h1 class="hill-title">king of the hill</h1><div class="hill-card">${king?coinCard(king):`<div class="hill-empty"><img src="/assets/pill-v1.svg" alt=""><div><span>the hill is waiting.</span><small>${connectionError?'Live coin data is not connected yet.':'No coin has reached 85% of its bonding-curve sale allocation yet.'}</small><a href="#launch">[be part of the first chapter]</a></div></div>`}</div></section><form class="classic-search search" id="board-search"><input id="search" aria-label="Search coins" placeholder="search for token" autocomplete="off" value="${e(query)}"><button type="submit">search</button><div id="search-results" class="search-results" hidden></div></form><section class="classic-list"><div class="board-tabs"><button data-action="sort" data-value="bump" class="${sort!=='watchlist'?'active':''}">board</button><button data-action="sort" data-value="watchlist" class="${sort==='watchlist'?'active':''}">watchlist</button><a href="#about">our mission</a></div><div class="board-controls"><label><span class="sr-only">Sort coins</span><select id="board-sort" aria-label="Sort coins"><option value="bump" ${sort==='bump'?'selected':''}>sort: bump order</option><option value="new" ${sort==='new'?'selected':''}>sort: creation time</option><option value="cap" ${sort==='cap'?'selected':''}>sort: market cap</option>${sort==='watchlist'?'<option value="watchlist" selected>sort: watchlist</option>':''}</select></label><label><span class="sr-only">Sort direction</span><select id="board-order" aria-label="Sort direction"><option value="desc" ${boardOrder==='desc'?'selected':''}>order: desc</option><option value="asc" ${boardOrder==='asc'?'selected':''}>order: asc</option></select></label><div class="board-switches"><div><span>show animations:</span><button type="button" data-action="board-motion" data-value="on" aria-pressed="${boardAnimations}">on</button><button type="button" data-action="board-motion" data-value="off" aria-pressed="${!boardAnimations}">off</button></div><div><span>include graduated:</span><button type="button" data-action="board-graduated" data-value="on" aria-pressed="${filter==='all'}">on</button><button type="button" data-action="board-graduated" data-value="off" aria-pressed="${filter==='curve'}">off</button></div></div><span id="coin-count">${connectionError?'awaiting live data':boardTotal+' coins'}</span><button class="board-refresh" data-action="refresh">[refresh]</button></div><div id="coin-grid" class="coin-grid">${filtered().map(coinCard).join('')||feedEmpty()}</div>${boardPagination()}<p class="board-data-note">Bump order follows finalized buys and sells. The board refreshes every 5 seconds and pauses while you hover over the coins. Curve coins earn King of the Hill at 85% of their sale allocation. OnePill qualifies when its Solana pool holds 45 SOL. The latest first-time qualifier holds the crown until another coin qualifies.</p></section>`}
function feedEmpty(){return `<div class="classic-empty"><p>${connectionError?'the coin board is waiting for its live feed.':loading?'loading coins…':sort==='watchlist'?'no saved coins yet.':'no coins found.'}</p><small>${connectionError?'Confirmed launches will appear here when the data service is connected.':sort==='watchlist'?'Star a coin to keep it here.':'Try another search or start a new coin.'}</small>${connectionError?'<a href="#status">[view launch status]</a>':'<a href="#launch">[start a new coin]</a>'}</div>`}
function welcome(){return `<div class="welcome"><div class="welcome-copy"><span class="eyebrow">YOUR IDEA. YOUR COMMUNITY.</span><h1>Small beginnings.<br><span class="green">Big possibilities.</span></h1><p>Give your coin a name. Choose its rules.<br>Build a community, then graduate to PumpSwap.</p><div class="welcome-actions"><a class="btn primary" href="#launch">Create a coin ${icon('arrow')}</a><a class="btn subtle" href="#about">Explore the rules ${icon('chevron')}</a></div><small>Wallet-signed launches · Clear rules from day one</small></div><div class="welcome-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><img src="/assets/pill-v1.svg" alt=""><span class="orbit-label label-top">01 / AN IDEA</span><span class="orbit-label label-bottom">02 / A COMMUNITY</span><span class="orbit-dot"></span></div></div>`}
function how(){return `<section class="how"><div class="section-head"><h2>From an idea to a coin.</h2><a class="green row" href="#about" style="font-size:12px">How it works ${icon('arrow')}</a></div><div class="steps">${[['Make it yours','A name, a ticker, a picture. Pick your rules and decide where the fees go.'],['Launch with a plan','Connect Phantom, review the costs, and approve your launch transactions in your wallet.'],['Let your community grow','Trade on Pill’s custom curve. Reach the target. Move to PumpSwap with the same token; the launch contract burns the LP tokens it receives.']].map(([title,text],i)=>`<div class="step"><span class="step-number">0${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}</div></section>`}
function field(name,label,placeholder='',type='text'){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${e(draft[name]??'')}" placeholder="${placeholder}" ${name==='name'?'maxlength="32"':name==='ticker'?'maxlength="10"':''}></label>`}
function options(name,values){return `<div class="segmented">${values.map(([v,label])=>`<button type="button" data-action="option" data-name="${name}" data-value="${v}" class="${draft[name]===v?'active':''}" aria-pressed="${draft[name]===v}">${label}</button>`).join('')}</div>`}
function quickModeWarning(){return `<aside class="developer-lock-warning" role="note"><strong>QUICK MODE: SELLING OPENS AFTER 1 HOUR</strong><p>On Pill’s curve, selling is locked for the first hour after activation. After that hour, holders can sell even if the coin has not migrated.</p><p>Developer purchases still have their separate <b>24-hour lock</b>. Quick Mode does not shorten that lock.</p></aside>`}
function developerLockWarning(){return `<aside class="developer-lock-warning" role="note"><strong>V1.1 DEVELOPERS: MANDATORY 24-HOUR TOKEN LOCK</strong><p>Your initial buy and later purchases from the developer wallet are locked for 24 hours. You cannot sell or transfer the locked tokens during that time. This rule cannot be switched off.</p><p><b>Migration is not required to unlock.</b> After the timer expires, you can sell on Pill before migration. Further developer purchases can extend the unlock time.</p></aside>`}
function launch(){
 if(draft.school==='onepill')return launchSchools()+onepillForm();
 const native=draft.school==='new',classic=native||draft.version!=='v1.1';
 let html=launchFull();
 const start=html.indexOf('<section class="panel"><h2>Set the rules</h2>'),end=html.indexOf('<section class="panel"><h2>The finishing touches</h2>');
 const selector=`<section class="panel launch-type-panel"><h2>Old School launch type</h2>${options('version',[['v1','Stealth Classic · V1'],['v1.1','Stealth · V1.1']])}</section>`;
 html=html.slice(0,start)+(native?'<section class="panel"><h2>New School · Holder Rewards</h2><p>Pump’s native SOL curve. Creator fees fund holder rewards distributed by Pump. Custom Pill rules do not apply.</p></section>':selector)+(classic?'':html.slice(start,end))+html.slice(end);
 if(classic){
  html=html.replace('Your connected wallet pays the on-chain costs and receives the developer allocation.','Choose an optional initial buy. Creation and your purchase are approved together in Phantom.');
  html=html.replace('A developer buy executes after the protection window and stays locked for 24 hours. It is exempt from the wallet cap.','Set 0 to launch without buying. Your initial buy includes the 2.2% platform fee and is limited to 1% of supply by the shared per-slot limit. Tokens go straight to your wallet, with no developer lock. Network and account costs are additional.');
  html=html.replace(/<div><span>Fee mode<\/span>[\s\S]*?<div><span>Graduates to/,'<div><span>Launch type</span><strong>Stealth Classic · V1</strong></div><div><span>Pre-migration fee</span><strong>2.2%</strong></div><div><span>Post-migration · PumpSwap</span><strong>0.30% native pool fee</strong></div><div><span>Graduates to');
  html=html.replace('No deposit address. Approve creation and activation directly in your wallet. Blocklists may require additional approvals.','Approve coin creation directly in your wallet. Classic settings are fixed.');
  html=html.replace('Pre-graduation positions stay in the program. Wallet token claims become available after graduation.','Purchased tokens go directly to your wallet.');
 }
 if(!classic){html=html.replace('<h2>The finishing touches</h2>','<h2>The finishing touches</h2>'+developerLockWarning());}
 if(!classic)html=html.replace('<div><span>Graduates to</span>', '<div><span>Pre-migration fee</span><strong>2.5% normal · opening tax may apply</strong></div><div><span>Post-migration · PumpSwap</span><strong>0.30% native pool fee</strong></div><div><span>Graduates to</span>');
 if(native){
 html=html.replace('Choose an optional initial buy. Creation and your purchase are approved together in Phantom.','Choose an optional initial buy. The review shows whether creation and purchase need one or two wallet approvals.').replaceAll('Stealth Classic · V1','New School · Holder Rewards').replace('2.2%</strong>','Pump native schedule</strong>').replace('0.30% native pool fee','Pump canonical pool schedule').replace('Set 0 to launch without buying. Your initial buy includes the 2.2% platform fee and is limited to 1% of supply by the shared per-slot limit. Tokens go straight to your wallet, with no developer lock. Network and account costs are additional.','Set 0 to launch without an initial buy. Pump’s native fees and network/account costs apply. Purchased tokens go directly to your wallet.').replace('Classic settings are fixed.','Pump’s native Holder Rewards settings apply.');
 }
 return launchSchools()+html;
}
function launchFull(){return `<form id="launch-form" class="launch-layout"><div class="launch-main"><section class="panel"><h1>Create a coin</h1><p class="panel-description" style="margin-top:8px">Your idea. Your community. Your rules. Let’s make something fun.</p><div class="identity-fields"><label class="field"><span>Picture</span><span class="upload">${imagePreview?`<img src="${imagePreview}" alt="Coin picture preview">`:icon('upload')+'<span>Add a picture</span><small>PNG, JPG · up to 4 MB</small>'}<input type="file" id="picture" accept="image/png,image/jpeg,image/webp" aria-label="Upload coin picture"></span></label><div class="stack"><div class="field-grid">${field('name','Name','Your coin’s name')}${field('ticker','Ticker','e.g. PILL')}</div><label class="field"><span>Description</span><textarea name="description" maxlength="2000" placeholder="What’s the story?">${e(draft.description)}</textarea></label></div></div><details style="margin-top:22px"><summary class="muted" style="cursor:pointer;font-size:12px">Metadata & links</summary><div class="stack" style="margin-top:15px">${field('twitter','X / Twitter (optional)','https://x.com/…')}${field('telegram','Telegram (optional)','https://t.me/…')}${field('website','Website (optional)','https://…')}${field('uri','Published metadata URI','https://…/metadata.json')}<small>Your picture and metadata are uploaded automatically when you review the launch. You can also supply an existing metadata URI.</small><button type="button" data-action="metadata" class="subtle">Download metadata template ${icon('arrow')}</button></div></details></section><section class="panel"><h2>Set the rules</h2><p class="panel-description">Pick what makes your coin better for the holders.</p><div class="rule"><div><h3>Bonding curve</h3><p>Amounts in SOL. Reach the raise target and move to PumpSwap. One billion tokens, six decimals.</p></div><div class="field-grid">${field('virtualQuote','Initial virtual SOL','30')}${field('targetQuote','Raise target · SOL','85')}</div></div><div class="rule"><div><h3>Launch mode</h3><p id="mode-help">${draft.mode==='quick'?'Selling on Pill opens one hour after activation, even without migration. Developer purchases remain locked for 24 hours.':'Buy and sell on the curve after the protection window.'}</p></div>${options('mode',[['standard','Buy & sell'],['quick','Quick bond']])}</div>${draft.mode==='quick'?quickModeWarning():''}<div class="rule"><div><h3>Where fees go</h3></div>${options('feeMode',[['burn','Burn'],['holders','Holders'],['liquidity','Liquidity'],['yap','Raiders']])}</div><div class="rule"><div><h3>Max per wallet</h3><p>Limits each wallet’s position until the coin bonds.</p></div><div><div class="row between" style="margin-bottom:12px"><small>0.5%</small><strong class="green" id="cap-value">${e(draft.cap)}%</strong><small>4%</small></div><input name="cap" aria-label="Max per wallet" type="range" min="0.5" max="4" step="0.5" value="${e(draft.cap)}"></div></div><div class="rule"><div><h3>Block certain wallets at launch</h3><p>Block selected wallets during the curve. Up to 10,000 addresses. Large lists add rent and launch time.</p></div><details ${draft.blocked?'open':''}><summary class="muted" style="font-size:12px;cursor:pointer">Add blocked wallets</summary><button type="button" data-action="kol-list" class="wide" style="margin-top:12px">Load known KOL list</button><small style="display:block;margin-top:10px">Public reference snapshot · Nov 4, 2026. Review addresses before use.</small><textarea name="blocked" aria-label="Blocked wallets" placeholder="One wallet address per line" style="margin-top:10px">${e(draft.blocked)}</textarea></details></div><div class="security-note">${icon('shield')}<span>Every launch has a randomized 1–4 slot sniper window with a 99% fee reserved for burns. Normal curve fees are 2.5%. Native PumpSwap fees apply after graduation.</span></div></section><section class="panel"><h2>The finishing touches</h2><p class="panel-description">Your connected wallet pays the on-chain costs and receives the developer allocation.</p><div class="stack"><div class="field"><span>Connected wallet</span><button type="button" data-action="wallet">${wallet?e(short(wallet)):'Connect Phantom or Solflare'} ${icon('wallet')}</button></div>${field('devBuy','Developer buy · SOL (optional)','0')}<div class="security-note">${icon('clock')}<span>A developer buy executes after the protection window and stays locked for 24 hours. It is exempt from the wallet cap.</span></div></div></section></div><aside class="launch-sidebar"><section class="panel"><span class="eyebrow">Your coin preview</span><div class="preview-coin"><img id="draft-art" src="${imagePreview||'/assets/pill-v1.svg'}" alt="Coin preview"><div><h3 id="draft-name">${e(draft.name||'Your next big idea')}</h3><small id="draft-symbol">$${e(draft.ticker||'TICKER')}</small></div></div><p id="draft-description" class="note">${e(draft.description||'Every great community starts somewhere.')}</p><div class="receipt"><div><span>Fee mode</span><strong id="draft-mode">${modeLabel[draft.feeMode]}</strong></div><div><span>Wallet cap</span><strong id="draft-cap">${e(draft.cap)}%</strong></div><div><span>Graduates to</span><strong class="green">PumpSwap</strong></div><div><span>Launch payment</span><strong>Direct from your wallet</strong></div><div><span>New mint suffix</span><strong>piLL</strong></div><div><span>Network & account costs</span><strong>Review in Phantom</strong></div></div><p class="note">A unique piLL mint address is reserved before review. Your wallet approves and pays for the launch.</p><button class="primary wide" type="submit">Review your launch ${icon('arrow')}</button><button class="subtle wide" type="button" data-action="save-draft" style="margin-top:8px">Save draft</button><p class="note">No deposit address. Approve creation and activation directly in your wallet. Blocklists may require additional approvals.</p></section><div class="security-note">${icon('shield')}<span>Pre-graduation positions stay in the program. Wallet token claims become available after graduation.</span></div></aside></form>`}
function about(){return `<article class="classic-mission"><img src="/assets/pill-v1.svg" alt="Pill V1" width="74" height="74"><h1>old is gold.</h1><h2>bring back the feeling.</h2><p>A simple board. A new idea. A community in the replies.</p><p>Pill V1 is about bringing back what made the earliest days feel like home: discovering a coin, watching it climb, and being there from the beginning.</p><p>Old School launches start on Pill’s custom curve: Stealth Classic V1 keeps the classic settings, while Stealth V1.1 adds selected rules and rewards. Trade through Pill before graduation. At the target, liquidity moves to PumpSwap and the launch contract burns its received LP tokens.</p><p>Stealth describes the trading route, not secrecy: mints and transactions are public on Solana. Mint recognition in a bot is not proof that the bot can trade the curve.</p><p>New School uses Pump’s native Holder Rewards mode. Launch on Pump and follow the coin here on Pill, with our community board and milestone history. Pump controls native fees, rewards and graduation. <a href="#docs">Read the launch guide.</a></p><a href="#launch">[start a new coin]</a></article><rule-studio expanded></rule-studio>${how()}`}
function raids(){return `<div class="page-heading row between"><div><h1>Make some noise.</h1><p>Find your coin. Join the conversation. Track verified raider rewards.</p></div><span class="tag">${icon('raids')} YAP</span></div><div class="two-col"><section class="panel"><h2>Community raids</h2><p class="panel-description" style="margin-top:8px">Select a coin to see its verified posts.</p><div class="coin-grid" style="grid-template-columns:1fr">${coins.filter(c=>c.mode==='yap'||!c.example).map(coinCard).join('')||empty('No Raider rewards coins yet','Coins with social rewards will appear here.')}</div></section><section class="panel stack"><h2>Your contribution counts.</h2><p class="muted" style="font-size:12px">Connect your wallet, link your X account and submit a post about a Raider rewards coin. Only verified, eligible posts enter the reward round.</p><button data-action="wallet">${wallet?e(short(wallet)):'Connect wallet'} ${icon('wallet')}</button><button data-action="link-x">Link your X account ${icon('external')}</button><label class="field"><span>Coin mint address</span><input id="raid-mint" placeholder="Solana mint address"></label><label class="field"><span>Your X post URL</span><input id="raid-url" placeholder="https://x.com/you/status/…"></label><button class="primary" data-action="submit-post">Submit for verification ${icon('arrow')}</button><p class="note">A submitted post is not a guaranteed reward. Verified holdings, eligibility and the available reward budget determine the allocation.</p></section></div>`}
function stats(){return `<div class="page-heading"><h1>Small coins. Real activity.</h1><p>${preview?'Example figures to preview the dashboard.':'Finalized, indexed activity from the launchpad.'}</p></div><div id="stats-content"><div class="stats-grid">${[['Coins launched',preview?'128':'—','Every idea starts somewhere'],['Curve volume',preview?'12,540 SOL':'—','Indexed curve trades only'],['Tokens burned',preview?'28.6M':'—','Removed from token supply'],['Holder distributions',preview?'84.2 SOL':'—','Indexed distributions']].map(([title,value,note])=>`<section class="panel stat"><span class="eyebrow">${title}</span><strong>${value}</strong><small>${note}</small></section>`).join('')}</div></div><div class="two-col"><section class="panel"><div class="section-head"><h2>V1.1 normal curve fees</h2><span class="tag">After protection</span></div><div style="display:flex;height:40px;gap:5px;margin:30px 0 18px"><div style="width:12%;background:var(--green);border-radius:7px"></div><div style="width:88%;background:#677972;border-radius:7px"></div></div><div class="row between"><strong class="green">0.3% of trades to the coin’s mode</strong><small>2.2% of trades to treasury</small></div><p class="note">Burns, holder rewards, liquidity or raiders. Classic charges 2.2%, all to the treasury. V1.1 charges 2.5% normally. During launch protection, 2.2% goes to treasury and the remaining tax funds burns. PumpSwap applies its own fees after graduation.</p></section><section class="panel"><h2>Open from day one.</h2><p class="muted" style="margin-top:15px;font-size:12px">The feed shows finalized records. Failed or refused buys are never counted as executed trades.</p><a href="#home" class="btn" style="margin-top:25px">Explore coins ${icon('arrow')}</a></section></div>`}
function chart(c){return `<div class="empty" style="border:0"><h3>Waiting for trades</h3><p>The chart uses actual finalized trades. No chart is drawn before the first trade.</p></div>`}
function coinAge(c){const t=Number(c.createdAt);if(!t)return "";const m=Math.max(0,Math.floor((Date.now()/1000-t)/60));return m<1?"just now":m<60?`${m} minutes ago`:m<1440?`about ${Math.floor(m/60)} hour${m>=120?"s":""} ago`:`${Math.floor(m/1440)} days ago`}
function detail(c){if(detailTab==='details'||(c.version!==11&&['rewards','raids'].includes(detailTab)))detailTab='discussion';selectedCoin=c;return `<div class="detail-layout"><div><div class="coin-classic-meta"><span class="coin-meta-name">${crownBadge(c)}${e(c.name)}</span><span>Ticker: ${e(c.symbol)}</span><span class="green">Market cap: <strong id="coin-market-cap">—</strong></span><span class="coin-ca">CA: <button data-action="copy" data-value="${e(c.mint)}" title="${e(c.mint)}"><span>${e(c.mint)}</span><span class="ca-copy-label">copy</span></button></span>${tags(c)}<span class="coin-created-by">created by ${walletBadge(c.creator)} <time>${e(coinAge(c))}</time></span></div><div hidden><span id="last-price"></span><span id="volume"></span><span id="curve-percent"></span></div><section class="chart"><div class="chart-controls"><span class="chart-symbol">${icon('search')}${e(c.symbol)}</span><select id="chart-timeframe" aria-label="Chart timeframe">${[[60,'1m'],[300,'5m'],[900,'15m'],[3600,'1h'],[14400,'4h'],[86400,'1d']].map(([v,label])=>`<option value="${v}" ${v===interval?'selected':''}>${label}</option>`).join('')}</select><button data-action="chart-style" aria-label="Switch between candles and line" title="Candles / line" aria-pressed="false">${icon('candles')}</button><details class="chart-indicators"><summary>ƒx <span>Indicators</span></summary><div><label><input type="checkbox" data-indicator="sma"> SMA (20)</label><label><input type="checkbox" data-indicator="ema"> EMA (20)</label></div></details><button data-action="chart-undo" aria-label="Undo drawing" title="Undo drawing">${icon('undo')}</button><button data-action="chart-redo" aria-label="Redo drawing" title="Redo drawing">${icon('redo')}</button><span class="chart-toolbar-spacer"></span><details class="chart-indicators chart-settings"><summary aria-label="Chart settings" title="Chart settings">${icon('settings')}</summary><div><label><input type="checkbox" data-chart-setting="grid" checked> Grid lines</label><label><input type="checkbox" data-chart-setting="volume" checked> Volume</label></div></details><button data-action="chart-fullscreen" aria-label="Expand chart" title="Expand chart">${icon('expand')}</button><button data-action="chart-image" title="Save chart image" aria-label="Save chart image">${icon('camera')}</button></div><div class="chart-workspace"><div class="chart-drawing-tools" aria-label="Chart drawing tools">${[['crosshair','Crosshair','crosshair'],['trend','Trend line: click two points','trend'],['horizontal','Horizontal line: click a level','horizontal'],['fib','Fibonacci retracement: click two points','fib'],['measure','Measure: click two points','ruler']].map(([id,label,svg])=>`<button data-action="draw-tool" data-value="${id}" aria-label="${label}" title="${label}" aria-pressed="${id==='crosshair'}">${icon(svg)}</button>`).join('')}<span class="drawing-divider"></span><button data-action="clear-drawings" aria-label="Clear drawings" title="Clear drawings">${icon('trash')}</button></div><div class="chart-canvas-area"><div class="chart-legend" id="chart-legend">${e(c.symbol)} · ${interval/60} · Pill</div><div class="chart-plot" id="chart-plot">${chart(c)}</div></div></div><div class="chart-bottom"><button data-action="chart-range" data-value="5">5d</button><button data-action="chart-range" data-value="1">1d</button><label class="chart-date" title="Go to date"><input type="date" id="chart-date" aria-label="Go to chart date"></label><span class="chart-toolbar-spacer"></span><time id="chart-clock"></time><button data-action="chart-percent" aria-pressed="false" title="Percentage scale">%</button><button data-action="chart-log" aria-pressed="false" title="Logarithmic scale">log</button><button data-action="chart-reset" title="Reset chart view and scale">auto</button></div><div class="chart-footer"><span id="chart-status">${c.example?'Illustrative prices · no trading':'Finalized trades · curve + PumpSwap'}</span><a href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">TradingView Lightweight Charts™</a></div></section><div class="data-tabs">${[['discussion','Thread'],['activity','Trades'],...(c.version===11?[['rewards','Rewards'],['raids','Verified posts']]:[])].map(([id,label])=>`<button data-action="detail-tab" data-value="${id}" class="${detailTab===id?'active':''}">${label}</button>`).join('')}</div><div id="detail-data">${detailBody(c)}</div></div><aside class="coin-detail-side"><section class="panel" id="crown-status">${crownPanel(c)}</section><section class="panel" id="curve-detail"></section><section class="panel" id="holder-distribution"><h2>Holder distribution</h2><p class="note">Loading finalized balances…</p></section><section class="panel trade" id="coin-trade-panel"><div class="segmented"><button data-action="side" data-value="buy" class="${side==='buy'?'active':''}">Buy</button><button data-action="side" data-value="sell" class="sell ${side==='sell'?'active':''}">Sell</button></div><p class="note" id="token-balance"></p><p class="error" id="trade-feedback" role="alert" hidden></p><div class="trade-options"><label for="amount">Amount in ${side==='buy'?'SOL':e(c.symbol)}</label><details class="trade-slippage"><summary>Set max slippage</summary><label><input type="number" id="slippage" aria-label="Maximum slippage percent" min="0" max="50" step="0.01" value="1">%</label></details></div><div class="amount-wrap"><input id="amount" inputmode="decimal" placeholder="0.00" value=""><span>${side==='buy'?'SOL':e(c.symbol)}</span></div><div class="amount-options"><button data-action="amount" data-value="">reset</button>${(side==='buy'?['0.01','0.05','0.1']:['25','50','100']).map(v=>`<button data-action="${side==='buy'?'amount':'sell-percent'}" data-value="${v}">${v}${side==='buy'?' SOL':'%'}</button>`).join('')}</div><button class="primary wide" data-action="trade" ${c.example?'disabled':''}>${c.example?'Preview · trading disabled':wallet?'place trade':'connect wallet to trade'}</button><p class="note">${c.version===2?'New School · Pump Holder Rewards. Pump’s native fee schedule applies. Holder payouts are distributed by Pump.':c.phase==='pumpswap'?'Graduated to PumpSwap. The launch contract burned the LP tokens it received.':'Old School: trade on Pill before graduation. External bots may recognize this mint without a working trade route. Review your quote before signing.'}</p></section><section class="panel coin-about" id="coin-about"><div class="coin-about-heading"><img src="${art(c)}" alt="${e(c.name)}"><div><h2>${e(c.name)} (ticker: ${e(c.symbol)})</h2><p class="muted">${e(c.description||'')}</p></div></div><div class="row" id="coin-social-links" style="gap:14px;margin-top:12px">${coinLinks(c)}</div><div class="receipt"><div><span>Creator</span><strong>${e(short(c.creator))}</strong></div><div><span>Venue</span><strong>${c.onepill?'Pangea · Solana':c.phase==='pumpswap'?'PumpSwap':c.version===2?'Pump native curve':'Pill · Old School curve'}</strong></div></div>${c.mint?`<button class="wide row between" data-action="copy" data-value="${e(c.mint)}">${e(short(c.mint))} ${icon('copy')}</button>`:'<small>Example artwork and coin. No mint exists.</small>'}</section></aside></div>`}
function detailBody(c){if(detailTab==='raids')return `<div id="verified-raids">${empty(c.example?'Example coin':'Loading verified posts…',c.example?'No real posts are associated with this example.':'Only verified submissions appear here.')}</div>`;if(detailTab==='details')return `<div class="panel stack"><h3>Token details</h3><div class="receipt"><div><span>Mint</span><span style="overflow-wrap:anywhere">${e(c.mint||'Example — no mint')}</span></div><div><span>Phase</span><span>${e(c.phase)}</span></div><div><span>Metadata URI</span><span style="overflow-wrap:anywhere">${e(c.uri||'—')}</span></div></div>${!c.example?'<button data-action="propose-metadata">Suggest a name or image update</button><p class="note">Holder proposals are subject to moderator selection after a 24-hour delay. The ticker stays fixed.</p>':''}</div>`;if(detailTab==='discussion')return `<div class="thread-jump"><a href="#" data-action="thread-bottom">[scroll to bottom]</a></div><div id="posts">${empty('Start the conversation',c.example?'Example coin — discussions are disabled.':'Loading discussion…')}</div><div class="thread-jump thread-jump-bottom"><a href="#" data-action="thread-top">[scroll to top]</a></div><form id="discussion-form" class="stack" style="margin-top:15px"><textarea name="message" aria-label="Your message" maxlength="2000" placeholder="Say something about this coin…" ${c.example?'disabled':''}></textarea><label class="field"><span>image (optional)</span><input type="file" name="replyImage" accept="image/png,image/jpeg,image/webp"></label><button class="primary" ${c.example?'disabled':''}>${wallet?'Post a reply':'Connect wallet to post'}</button></form>`;if(detailTab==='rewards')return `<div id="rewards">${empty('Your rewards, in one place',c.example?'Example coin — no rewards have accrued.':wallet?'Loading reward proofs…':'Connect your wallet to check your reward rounds.',!c.example&&!wallet?'<button class="btn" data-action="wallet">Connect wallet</button>':'')}</div>`;return `<div id="activity">${empty(c.example?'No real trades':'Loading activity…',c.example?'Example coins cannot be traded.':'Only finalized events are displayed.')}</div>`}
const launchStepNames={create_launch:'Create your coin',upload_blocklist:'Save wallet protections',request_activation:'Set up launch protection',activate:'Enable trading',execute_developer_buy:'Complete your initial buy'};
function status(){const record=readDirect(),done=record&&record.step>=record.stageCount;const kinds=record?.stageKinds||Array.from({length:record?.stageCount||0},(_,i)=>'step_'+i);return `<div class="page-heading"><h1>${done?'Launch confirmed':directBusy?'Launching your coin…':'Finish your launch'}</h1><p>Approve each request in your wallet. We handle the waiting between confirmations.</p></div><section class="panel" style="max-width:720px">${record?`<h2>${e(record.payload.config.name)} <span class="muted">$${e(record.payload.config.ticker)}</span></h2><p class="note">${record.stageCount} wallet confirmations in total. Keep this page open until your coin is ready.</p><ol class="launch-guide">${kinds.map((kind,i)=>`<li class="${i<record.step?'complete':i===record.step?'current':''}" ${i===record.step?'aria-current="step"':''}><span class="launch-step-number">${i<record.step?'✓':i+1}</span><span>${e(launchStepNames[kind]||'Wallet confirmation '+(i+1))}</span><small>${i<record.step?'Confirmed':i===record.step?(record.pending?'Confirming…':directBusy?'In progress':'Next'):''}</small></li>`).join('')}</ol>${directBusy?'<div class="launch-loading" role="status"><span class="launch-spinner" aria-hidden="true"></span><strong>Keep this page open</strong></div>':''}<p id="direct-status-note" class="note" aria-live="polite">${e(record.failure||directMessage||(done?'Your launch is confirmed. Waiting for the coin page to update.':directBusy?'Follow the request in your wallet.':'Click Continue, then approve the next request in your wallet. Your completed steps are saved.'))}</p><div class="row" style="margin-top:20px">${done?'<a class="btn primary" href="#home">View coins</a>':`<button class="primary" data-action="continue-direct" ${record.failure||directBusy?'disabled':''}>${directBusy?'Launch in progress…':'Continue in wallet'}</button>${directBusy?'<button data-action="pause-direct">Pause</button>':''}`}${record.failure?'<button data-action="retry-direct">Review failed step again</button>':''}</div><details style="margin-top:24px"><summary>Transaction details</summary><p class="note">Mint: ${e(record.mint)}</p>${record.history.map(h=>`<div class="data-row"><span>${e(launchStepNames[h.kind]||h.kind)}</span><span>${e(h.state)}</span><button data-action="copy" data-value="${e(h.signature)}">${e(short(h.signature))}</button></div>`).join('')}</details>`:empty('No active launch','Connect the wallet and browser you used to launch. Your saved progress stays in that browser.',`<a href="#launch" class="btn primary">Create a coin</a>`)}</section>`}

function render(){disposeOnepillMarket?.();disposeOnepillMarket=null;destroyChart();routeEpoch++;const r=route();if(r.startsWith('onepill/')){shell(empty('Loading OnePill…','Checking the five-chain launch.'));loadOnepill(r.split('/')[1],routeEpoch);return}if(r.startsWith('profile/')){shell(empty('Loading profile…','Checking indexed coins and finalized balances.'));loadProfile(r.split('/')[1],routeEpoch);return}if(r.startsWith('coin/')&&r.split('/')[1].startsWith('0x')){history.replaceState(history.state,'','/onepill/'+r.split('/')[1]);render();return}if(r.startsWith('coin/')){const c=coins.find(c=>c.id===r.split('/')[1]||c.mint===r.split('/')[1]);if(c){rememberCoinRoute(c);if(c.onepill){loadOnepill(c.id,routeEpoch);return}shell(detail(c));placeTradePanel();loadDetail(c,routeEpoch);return}shell(empty('Loading coin…','Checking its finalized launch status.'));loadCoinRoute(r.split('/')[1],routeEpoch);return}shell(({home,launch,raids,stats,about,status,docs}[r.split('/')[0]]??home)());if(r==='stats'&&!preview)loadStats(routeEpoch);}
function bindBoard(){document.querySelector('#board-search')?.addEventListener('submit',event=>{event.preventDefault();query=document.querySelector('#search').value;document.querySelector('#search-results').hidden=true;boardPage=1;loadCoins()});document.querySelector('#board-sort')?.addEventListener('change',event=>{sort=event.target.value;boardPage=1;cursor=null;loadCoins()});document.querySelector('#board-order')?.addEventListener('change',event=>{boardOrder=event.target.value;boardPage=1;loadCoins()})}
function bindForms(){bindOnepill();document.querySelector(".classic-launch-rules")?.addEventListener("toggle",event=>{advancedRulesOpen=event.target.open});document.querySelector('#launch-form')?.addEventListener('submit',reviewLaunch);document.querySelector('#launch-form')?.addEventListener('input',evt=>{if(evt.target.name){draft[evt.target.name]=evt.target.value;updateDraftPreview()}});document.querySelector('#picture')?.addEventListener('change',evt=>{const f=evt.target.files[0];if(!f)return;if(f.size>4*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('Choose a PNG, JPG or WebP under 4 MB.');return}if(imagePreview)URL.revokeObjectURL(imagePreview);imageFile=f;uploadedMetadataKey='';draft.uri='';imagePreview=URL.createObjectURL(f);render()});document.querySelector('#search')?.addEventListener('input',evt=>{query=evt.target.value;showSearch();if(route()==='home'){clearTimeout(boardSearchTimer);boardSearchTimer=setTimeout(()=>{boardPage=1;loadCoins()},300)}});document.querySelector('#search')?.addEventListener('focus',showSearch);document.querySelector('#discussion-form')?.addEventListener('submit',async evt=>{evt.preventDefault();if(!wallet)return walletDialog();try{await ensureSession();const form=new FormData(evt.target),file=form.get('replyImage');let image=null;if(file?.size){if(file.size>4*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPG or WebP under 4 MB.');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const uploaded=await api.request('/media',{method:'POST',body:{name:'Discussion image',symbol:'REPLY',description:'',image:encoded}});image=new URL(uploaded.image).pathname}await api.postDiscussion(selectedCoin.mint,form.get('message'),image);evt.target.reset();threadBefore=null;threadPages=[];loadDetail(selectedCoin,routeEpoch)}catch(err){toast(errorText(err))}})}
function updateDraftPreview(){for(const [id,value]of [['draft-name',draft.name||'Your next big idea'],['draft-symbol','$'+(draft.ticker||'TICKER')],['draft-description',draft.description||'Every great community starts somewhere.'],['draft-cap',draft.cap+'%'],['cap-value',draft.cap+'%']]){const el=document.getElementById(id);if(el)el.textContent=value}}
function showSearch(){const results=document.querySelector('#search-results');if(!results)return;if(!query){results.hidden=true;return}const matches=coins.filter(c=>[c.name,c.symbol,c.mint].some(v=>(v??'').toLowerCase().includes(query.toLowerCase()))).slice(0,6);results.innerHTML=matches.map(c=>`<a href="/coin/${e(c.mint||c.id)}"><img src="${art(c)}" alt=""><strong>${e(c.name)}</strong><small>$${e(c.symbol)}</small></a>`).join('')||'<p>No matching coins.</p>';results.hidden=false}
function updateCoinGrid(){const el=document.querySelector('#coin-grid');if(el){el.innerHTML=filtered().map(coinCard).join('')||feedEmpty();document.querySelector('#coin-count').textContent=connectionError?'Awaiting live data':boardTotal+' coins';document.querySelector('.board-pagination')?.remove();el.insertAdjacentHTML('afterend',boardPagination())}}
async function loadCoins(){const request=++coinsRequest;loading=true;try{capabilities=await api.capabilities();const params=new URLSearchParams({limit:'48',page:String(boardPage),sort:['new','cap'].includes(sort)?sort:'bump',direction:boardOrder,search:query,graduated:filter==='curve'?'0':'1'});const [data]=await Promise.all([api.request('/coins/board?'+params),getDollarQuote().catch(()=>null)]);if(preview||request!==coinsRequest)return;const mapped=data.coins.map(c=>({...c,id:c.launch||c.id,description:c.description||'',example:false}));bumpedCoins=new Set(mapped.filter(c=>{const old=coins.find(x=>x.id===c.id);return old&&Number(c.bumpSlot)>Number(old.bumpSlot||old.created_slot)}).map(c=>c.id));coins=mapped;boardPage=data.page;boardPages=data.pages;boardTotal=data.total;cursor=null;kingOfTheHill=data.kingOfTheHill?{...data.kingOfTheHill,id:data.kingOfTheHill.launch||data.kingOfTheHill.id,description:data.kingOfTheHill.description||'',example:false}:null;connectionError=''}catch(err){if(request!==coinsRequest||preview)return;connectionError=errorText(err);if(!coins.length)coins=[]}finally{loading=false;if(!preview&&request===coinsRequest){if(route()==='home'&&document.querySelector('#coin-grid')){updateCoinGrid();const hill=document.querySelector('.hill-card');if(hill&&kingOfTheHill)hill.innerHTML=coinCard(kingOfTheHill)}else if(!route().startsWith('onepill/'))render();hydrateCoinLabels()}}}
function boardPagination(){const start=Math.max(1,Math.min(boardPage-2,boardPages-4));const pages=Array.from({length:Math.min(5,boardPages)},(_,i)=>start+i);return `<nav class="thread-pagination board-pagination" aria-label="Board pages"><span aria-hidden="true">[</span>${pages.map(n=>n===boardPage?`<span aria-current="page">${n}</span>`:`<button data-action="board-page" data-value="${n}" aria-label="Board page ${n}">${n}</button>`).join('')}<span aria-hidden="true">]</span></nav>`}

let statsPending=false;
async function loadStats(epoch){if(statsPending)return;statsPending=true;try{const data=await api.stats();if(epoch!==routeEpoch)return;const el=document.querySelector('#stats-content');el.innerHTML=`<p class="note" id="stats-freshness">${data.indexerHealthy?'Indexer current':'Indexer catching up'} · ${data.indexedAt?'Last indexed '+e(new Date(data.indexedAt*1000).toLocaleTimeString()):'Index timestamp unavailable'} · refreshes every 5 seconds</p><div class="stats-grid">${[['Curve volume',formatUnits(data.curveVolumeLamports,9,6)+' SOL'],['Curve fees',formatUnits(data.curveFeesLamports,9,6)+' SOL'],['Tokens burned',formatUnits(data.tokensBurnedRaw,6,2)],['Old School holder distributions',formatUnits(data.holderRewardsLamports,9,6)+' SOL']].map(([label,value])=>`<section class="panel stat"><span class="eyebrow">${label}</span><strong>${value}</strong><small>Finalized indexed records</small></section>`).join('')}</div>`}catch(err){if(epoch===routeEpoch){const note=document.querySelector('#stats-freshness');if(note)note.textContent='Refresh failed · showing the last successful totals · retrying';else document.querySelector('#stats-content').innerHTML=empty('Stats unavailable',errorText(err))}}finally{statsPending=false}}
async function loadDetail(c,epoch,background=false){if(c.onepill){if(detailTab==='discussion')await loadThread(c,epoch,threadBefore);return}if(c.example)return;try{const full=await api.coin(c.id);if(epoch!==routeEpoch)return;if(full.coin){Object.assign(c,full.coin);document.querySelector('#crown-status').innerHTML=crownPanel(c);document.querySelector('#coin-social-links').innerHTML=coinLinks(c)}const market=full.market;if(market){document.querySelector('#last-price').textContent=tokenPrice(market.lastExecutionPriceSol);document.querySelector('#volume').textContent=formatUnits(market.volumeLamports24h)}if(!background)loadCandles(c,epoch);loadHolders(c,epoch);loadLaunchRules(c,epoch);updateDollarCap(c);loadWalletBalance(c,epoch);if(detailTab==='activity'&&(!background||tradeCursor))await loadTrades(c,epoch,tradeCursor);if(detailTab==='discussion')await loadThread(c,epoch,threadBefore);if(detailTab==='raids'){const data=await api.raids(c.mint);if(epoch!==routeEpoch)return;document.querySelector('#verified-raids').innerHTML=data.items.map(p=>`<article class="panel row between" style="margin-bottom:10px"><div><strong>${e(short(p.wallet))}</strong><p class="note">Verified at round freeze</p></div><a class="btn" href="https://x.com/i/status/${e(p.postId)}" target="_blank" rel="noopener noreferrer">View post ${icon('external')}</a></article>`).join('')||empty('No verified posts yet','Eligible submissions appear after verification.')}if(detailTab==='rewards'&&wallet)await loadRewards(c,epoch)}catch(err){if(epoch===routeEpoch){const el=document.querySelector('#activity')??document.querySelector('#posts')??document.querySelector('#rewards')??document.querySelector('#verified-raids');if(el)el.innerHTML=empty('Could not load data',errorText(err))}}}
let candleRequest=0;
async function loadCandles(c,epoch){const loadKey=c.id+':'+epoch+':'+interval;if(pendingCandleLoads.has(loadKey))return;pendingCandleLoads.add(loadKey);const request=++candleRequest,requestedInterval=interval;try{const [data,quote,holders]=await Promise.all([api.candles(c.id,requestedInterval),getDollarQuote(),getHolders(c)]);if(quote.expiresAt<=Date.now())throw Error('Dollar price temporarily unavailable');if(epoch!==routeEpoch||request!==candleRequest)return;const el=document.querySelector('#chart-plot');if(!updateChart(el,data.candles??[],c.id+':'+requestedInterval,holders.totalSupplyRaw,quote.price)){destroyChart();el.innerHTML=empty('No trades yet','The chart starts with the first confirmed buy or sell.')}document.querySelector('#chart-status').textContent=data.missingTimestampTrades?'Syncing trade timestamps…':'Updated '+new Date().toLocaleTimeString()+' · finalized trades';}catch(err){if(epoch===routeEpoch&&request===candleRequest){document.querySelector('#chart-status').textContent='Chart refresh failed · retrying';if(!document.querySelector('#chart-plot canvas'))document.querySelector('#chart-plot').innerHTML=empty('Chart unavailable',errorText(err));}}finally{pendingCandleLoads.delete(loadKey)}}
let dollarQuote=null,dollarRequest=null;
async function updateDollarCap(c){const el=document.querySelector('#coin-market-cap');try{await getDollarQuote();if(selectedCoin!==c||!el?.isConnected)return;el.textContent=dollarQuote.expiresAt>Date.now()?compactUsd((c.capSol??Number(c.cap))*dollarQuote.price):'—';el.title='USD estimate using SOL/USD; market cap is not liquidity.';const graduation=document.querySelector('#graduation-market-cap');if(graduation)graduation.textContent=dollarQuote.expiresAt>Date.now()?compactUsd(c.graduationCapSol*dollarQuote.price):'—'}catch{if(el?.isConnected)el.textContent='—';const graduation=document.querySelector('#graduation-market-cap');if(graduation)graduation.textContent='—'}}
async function loadWalletBalance(c,epoch){const owner=wallet;if(!owner)return;try{const b=await api.request('/wallet-balance?mint='+encodeURIComponent(c.mint)+'&wallet='+encodeURIComponent(owner));if(epoch===routeEpoch&&wallet===owner){const el=document.querySelector('#token-balance');if(el)el.textContent='Your balance: '+formatUnits(b.balanceRaw,6,4)+' '+c.symbol}}catch{if(epoch===routeEpoch){const el=document.querySelector('#token-balance');if(el)el.textContent='Balance temporarily unavailable'}}}
async function walletDialog(){if(wallet){location.hash='#profile/'+wallet;return}if(preview){showDialog('Connect your wallet',`<img src="/assets/pill-v1.svg" width="60" alt="Pill V1 gold-ring capsule"><p class="notice">You’re exploring the design preview. Switch to backend data to connect a wallet when the service is available.</p><button class="primary wide" data-action="source">View backend data ${icon('arrow')}</button>`);return}try{const {availableWallets}=await import('./wallet.js');const wallets=availableWallets();showDialog('Connect your wallet',`<p class="notice">Connect Phantom or Solflare. Your private keys stay in your wallet; transactions require your approval.</p>${wallets.length?wallets.map(([name],i)=>`<button class="wallet-option" data-action="connect-provider" data-value="${i}">${e(name)} ${icon('arrow')}</button>`).join(''):'<p class="notice">No Solana wallet was detected. Open this site in a browser with Phantom or Solflare installed.</p>'}<div id="wallet-error" class="error"></div>`)}catch(err){toast(errorText(err))}}
async function connectProvider(i){const button=modal.querySelector(`[data-value="${i}"]`);button.disabled=true;try{const module=await import('./wallet.js');const choice=module.availableWallets()[i];provider=choice[1];localStorage.setItem('pill-wallet-provider',choice[0]);const connected=await provider.connect();wallet=(connected.publicKey??provider.publicKey).toString();authenticated=false;draft.wallet=wallet;observeProvider(provider);modal.close();render();toast('Wallet connected.')}catch(err){modal.querySelector('#wallet-error').textContent=errorText(err);button.disabled=false}}
function saveDraft(){localStorage.setItem('mint-draft',JSON.stringify(draft));toast('Draft saved on this device. Your picture stays in this session.')}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let reviewedPayload=null,launchReviewBusy=false;
async function reviewLaunch(evt){evt.preventDefault();if(launchReviewBusy)return;if(!wallet)return walletDialog();launchReviewBusy=true;draft.wallet=wallet;try{const {validateAddress}=await import('./wallet.js');const curve=draft.version==='v1.1'?{supply:'1000000000000000',saleTokens:'800000000000000',virtualTokens:'1000000000000000',virtualQuote:decimalUnits(draft.virtualQuote),targetQuote:decimalUnits(draft.targetQuote),protectionSlots:'4'}:{};if(draft.school!=='new'&&draft.version==='v1.1'&&(BigInt(curve.virtualQuote)<=0n||BigInt(curve.targetQuote)<=0n))throw Error('Curve amounts must be greater than zero.');await publishDraftMetadata();await ensureSession();reviewedPayload=launchPayload(draft.school==='new'?{...draft,version:'v1'}:draft,{curve,requestId:crypto.randomUUID().replaceAll('-',''),validateAddress});let direct=null;if(config.directLaunchEnabled&&capabilities?.readyForFunds){const module=await import(draft.school==='new'?'./native-pump.js':'./direct-launch.js');const launchOwner=wallet,controller=new AbortController(),cancelSearch=()=>controller.abort();showDialog('Preparing your launch',`<p class="notice">Reserving a unique piLL mint address. Your wallet will approve the launch next.</p><button class="wide" data-action="close">Cancel</button>`);modal.addEventListener('close',cancelSearch,{once:true});window.addEventListener('hashchange',cancelSearch,{once:true});try{direct=await module.prepareDirectLaunch(config,reviewedPayload,launchOwner,{signal:controller.signal,reserveMint:async()=>{try{return await api.request('/launch/mint/reserve',{method:'POST',body:{requestId:reviewedPayload.requestId},signal:controller.signal})}catch(error){if(error.message==='mint_reserve_replenishing')throw Error('All prepared piLL addresses are currently reserved. The background reserve is refilling—please retry shortly. No funds were sent.');if(error.message==='mint_reservation_limit')throw Error('This wallet has reached today’s mint reservation limit. No funds were sent.');throw error}},onProgress:attempts=>{const el=document.querySelector('#vanity-progress');if(el)el.textContent=attempts.toLocaleString()+' addresses checked…'}});if(wallet!==launchOwner)throw Error('Your wallet changed. Review the launch again.')}finally{modal.removeEventListener('close',cancelSearch);window.removeEventListener('hashchange',cancelSearch);modal.close()}}pendingDirect=direct;showDialog('Launch from your wallet',`${draft.school!=='new'&&draft.version==='v1.1'?developerLockWarning()+(draft.mode==='quick'?quickModeWarning():''):''}<div class="preview-coin"><img src="${imagePreview||'/assets/pill-v1.svg'}" alt=""><div><h3>${e(draft.name)}</h3><small>$${e(draft.ticker.toUpperCase())}</small></div></div><div class="receipt"><div><span>Wallet</span><strong>${e(short(wallet))}</strong></div><div><span>Fee mode</span><strong>${draft.school==='new'?'Native Holder Rewards':draft.version==='v1.1'?modeLabel[draft.feeMode]:'Stealth Classic · 2.2%'}</strong></div><div><span>Developer buy</span><strong>${e(draft.devBuy||'0')} SOL</strong></div>${direct?`<div><span>Mint address</span><strong style="overflow-wrap:anywhere">${e(direct.mint)}</strong></div>`:''}<div><span>Wallet approvals</span><strong>${direct?.automatic?direct.stageCount-1-(BigInt(direct.payload.config.developerBuyLamports??'0')>0n?1:0):direct?direct.stageCount:'Quoted after deployment'}</strong></div><div><span>Blocked wallets</span><strong>${reviewedPayload.blockedWallets.length}</strong></div>${direct?`<div><span>Oracle fee</span><strong>${formatUnits(direct.oracleFeeLamports,9,9)} SOL</strong></div>`:''}</div><p class="notice">Phantom signs each transaction. You pay network fees, account creation costs and any developer buy directly. ${draft.school==='new'?'Pump native fees apply. Creator fees fund holders. If two approvals are shown, creation happens first; the initial buy is separate and its price can change.':draft.version==='v1.1'?(direct?.automatic?'Approve the launch. Protection and your initial purchase finish automatically. Large blocklists may require additional approvals.':'We automatically prepare each protection step and prompt your wallet when it is ready. Keep this page open until launch completes.'):'Stealth Classic V1 creates the coin and includes your optional initial buy in one transaction, with fixed classic settings.'}</p><button data-action="start-direct" class="primary wide" ${!direct?'disabled':''}>Approve launch in Phantom ${icon('arrow')}</button>${!direct?'<p class="note">The launch program has not been deployed and configured yet. No funds will be requested.</p>':''}<button class="subtle wide" data-action="save-draft">Save draft</button><div id="launch-error" class="error"></div>`)
}catch(err){if(err.name!=='AbortError')toast(errorText(err))}finally{launchReviewBusy=false}}
let preparedTrade=null,socialProofs=[];
async function trade(){const feedback=document.querySelector('#trade-feedback');if(feedback){feedback.hidden=true;feedback.textContent=''}if(!wallet)return walletDialog();if(tradePending){await recoverPendingTrade();if(tradePending)return toast('Checking your previous transaction. Please wait for a confirmed result before retrying.');}if(!capabilities?.readyForFunds)return toast('Trading is not enabled for this deployment.');if(selectedCoin.phase==='pumpswap'){showDialog('Trade on PumpSwap',`<p class="notice">This coin has graduated. Use its exact mint address to trade on PumpSwap. Native PumpSwap fees apply.</p><button data-action="copy" data-value="${e(selectedCoin.mint)}" class="wide">Copy mint address ${icon('copy')}</button><a href="https://swap.pump.fun" target="_blank" rel="noopener noreferrer" class="btn primary wide" style="margin-top:12px">Open PumpSwap ${icon('external')}</a>`);return}try{const amount=decimalUnits(document.querySelector('#amount').value,side==='buy'?9:6);if(BigInt(amount)<=0n)throw Error('Enter an amount greater than zero.');const tradeOwner=wallet;const slippageBps=Number(decimalUnits(document.querySelector('#slippage').value,2));const tradeButton=document.querySelector('[data-action=trade]');if(tradeButton){tradeButton.disabled=true;tradeButton.textContent='Getting quote…'}preparedTrade=selectedCoin.version===2?await (await import('./native-pump.js')).prepareTrade(config,{mint:selectedCoin.mint,owner:wallet,side,amount,slippageBps:Number(decimalUnits(document.querySelector('#slippage').value,2))}):await (await import('./wallet.js')).prepareWalletTrade(config,{mint:selectedCoin.mint,owner:tradeOwner,version:selectedCoin.version===1?'v1':'v1.1',side,amount,slippageBps});if(wallet!==tradeOwner)throw Error('Wallet changed. Request a new quote.');showDialog('Review '+side,`<p class="note">Signing wallet: ${e(short(tradeOwner))}</p><p class="notice">Review this quote before approving it in your wallet. Expired quotes must be requested again.</p><pre style="white-space:pre-wrap;font-size:11px;max-height:250px;overflow:auto">${e(JSON.stringify(preparedTrade.quote,null,2))}</pre><button class="primary wide" data-action="sign-trade">Approve in wallet</button><div class="error" id="trade-error"></div>`)}catch(err){if(err.status===401||err.message==='unauthenticated')authenticated=false;const message=errorText(err);const feedback=document.querySelector('#trade-feedback');if(feedback){feedback.hidden=false;feedback.textContent=message}toast(message)}finally{const button=document.querySelector('[data-action=trade]');if(button){button.disabled=false;button.textContent=wallet?'place trade':'connect wallet to trade'}}}
async function signTrade(){
 const button=modal.querySelector('[data-action="sign-trade"]'),error=modal.querySelector('#trade-error');if(!button||button.disabled||tradePending)return;
 button.disabled=true;tradePending=true;error.textContent='Waiting for wallet approval…';
 try{
  const {sendPrepared}=await import(preparedTrade?.nativePump?'./native-pump.js':'./wallet.js');
  const result=await sendPrepared(provider,preparedTrade,config,record=>sessionStorage.setItem('mint-pending-trade',JSON.stringify(record)));
  error.textContent='Submitted: '+result.signature+'. Waiting for finality…';
  try{await result.confirm();sessionStorage.removeItem('mint-pending-trade');tradePending=false;modal.close();toast('Transaction finalized.');render()}
  catch{error.textContent='Transaction outcome pending. Keep this signature: '+result.signature+'. Do not submit again until it is reconciled.'}
 }catch(err){
  tradePending=!!sessionStorage.getItem('mint-pending-trade');
  error.textContent=tradePending?'Submission status is uncertain. Your transaction ID is saved. Checking its outcome before allowing another trade.':errorText(err);
 }finally{if(!tradePending&&button.isConnected){button.disabled=false;button.dataset.action='refresh-trade';button.textContent='Get a fresh quote'}}
}

document.addEventListener('click',async evt=>{const button=evt.target.closest('[data-action]');if(!button){if(!evt.target.closest('.search'))document.querySelector('#search-results')?.setAttribute('hidden','');return}const action=button.dataset.action,v=button.dataset.value;try{if(action==='pause-direct'){directPaused=true;toast('Launch will pause after the current wallet request or confirmation. Progress is saved.')}else if(action==='edit-profile'){await editOwnProfile()}else if(action==='chart-undo'){undoChartDrawing()}else if(action==='chart-redo'){redoChartDrawing()}else if(action==='chart-range'){chartRange(Number(v))}else if(action==='chart-style'){const on=button.getAttribute('aria-pressed')!=='true';chartDisplay('line',on);button.setAttribute('aria-pressed',String(on))}else if(action==='chart-percent'){const on=button.getAttribute('aria-pressed')!=='true';setChartScale(on?2:0);button.setAttribute('aria-pressed',String(on));document.querySelector('[data-action=chart-log]').setAttribute('aria-pressed','false')}else if(action==='draw-tool'){setDrawTool(v);document.querySelectorAll('[data-action=draw-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}else if(action==='clear-drawings'){clearChartDrawings()}else if(action==='chart-image'){saveChartImage()}else if(action==='chart-reset'){resetChart();setChartScale(0);document.querySelectorAll('[data-action=chart-log],[data-action=chart-percent]').forEach(b=>b.setAttribute('aria-pressed','false'))}else if(action==='chart-log'){const on=button.getAttribute('aria-pressed')!=='true';setChartLog(on);document.querySelector('[data-action=chart-percent]').setAttribute('aria-pressed','false');button.setAttribute('aria-pressed',String(on))}else if(action==='chart-fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.chart').requestFullscreen()}else if(action==='profile-tab'){profileTab=v;profilePage=0;renderProfile(routeEpoch)}else if(action==='profile-page'){profilePage=Math.max(0,Number(v)||0);loadProfileContent(routeEpoch)}else if(action==='sell-percent'){if(!wallet)return walletDialog();const b=await api.request('/wallet-balance?mint='+encodeURIComponent(selectedCoin.mint)+'&wallet='+encodeURIComponent(wallet));document.querySelector('#amount').value=formatUnits((BigInt(b.balanceRaw)*BigInt(v)/100n).toString(),6,6).replaceAll(',','')}else if(action==='profile-auth'){await ensureSession();render()}else if(action==='trades-page'){const page=Number(v);if(Number.isInteger(page)&&page>=0&&page<tradePages.length){tradeCursor=tradePages[page];tradePages=tradePages.slice(0,page);await loadTrades(selectedCoin,routeEpoch,tradeCursor)}}else if(action==='trades-next'){tradePages.push(tradeCursor);tradeCursor=v;await loadTrades(selectedCoin,routeEpoch,tradeCursor)}else if(action==='trades-prev'){tradeCursor=tradePages.pop()??null;await loadTrades(selectedCoin,routeEpoch,tradeCursor)}else if(action==='thread-bottom'||action==='thread-top'){evt.preventDefault();document.querySelector(action==='thread-bottom'?'#discussion-form':'#posts')?.scrollIntoView({behavior:'smooth'});}else if(action==='thread-page'){const page=Number(v);if(Number.isInteger(page)&&page>=0&&page<threadPages.length){threadBefore=threadPages[page];threadPages=threadPages.slice(0,page);await loadThread(selectedCoin,routeEpoch,threadBefore)}}else if(action==='thread-next'){threadPages.push(threadBefore);threadBefore=Number(v);await loadThread(selectedCoin,routeEpoch,threadBefore)}else if(action==='thread-prev'){threadBefore=threadPages.pop()??null;await loadThread(selectedCoin,routeEpoch,threadBefore)}else if(action==='like-comment'){if(!wallet)return walletDialog();await ensureSession();const id=Number(v),key=wallet+':'+id,result=await api.likeDiscussion(id,!likedPosts.has(key));result.liked?likedPosts.add(key):likedPosts.delete(key);await loadThread(selectedCoin,routeEpoch,threadBefore)}else if(action==='board-motion'){boardAnimations=v==='on';localStorage.setItem('pill-v1-animations',v);document.body.classList.toggle('no-board-motion',!boardAnimations);render()}else if(action==='board-graduated'){filter=v==='on'?'all':'curve';boardPage=1;render();loadCoins()}else if(action==='close')modal.close();else if(action==='theme'){document.body.classList.toggle('light');localStorage.setItem('mint-theme',document.body.classList.contains('light')?'light':'dark')}else if(action==='sort'){sort=v;boardPage=1;render();loadCoins()}else if(action==='filter'){filter=v;render()}else if(action==='favorite'){favorites.has(button.dataset.id)?favorites.delete(button.dataset.id):favorites.add(button.dataset.id);localStorage.setItem('mint-favorites',JSON.stringify([...favorites]));render()}else if(action==='option'){draft[button.dataset.name]=v;render()}else if(action==='save-draft')saveDraft();else if(action==='kol-list'){const response=await fetch('/assets/kol-wallets.json');const data=await response.json();draft.blocked=[...new Set([...draft.blocked.split(/[\s,]+/).filter(Boolean),...data.wallets])].join('\n');render();toast(data.wallets.length+' addresses added. Review the list and quoted rent.')}else if(action==='metadata')download('metadata-template.json',{name:draft.name,symbol:draft.ticker,description:draft.description,image:'REPLACE_WITH_PUBLISHED_IMAGE_URI',external_url:''});else if(action==='wallet')await walletDialog();else if(action==='connect-provider')await connectProvider(Number(v));else if(action==='disconnect'){localStorage.removeItem('pill-wallet-provider');try{await api.logout()}catch{}await provider?.disconnect();wallet='';provider=null;authenticated=false;modal.close();render()}else if(action==='refresh'){if(preview)toast('You’re viewing example coins.');else await loadCoins()}else if(action==='board-page'){boardPage=Number(v);await loadCoins();document.querySelector('.board-controls')?.scrollIntoView({block:'start'});}else if(action==='side'){side=v;render()}else if(action==='amount')document.querySelector('#amount').value=v;else if(action==='interval'){interval=Number(v);render()}else if(action==='detail-tab'){detailTab=v;if(selectedCoin?.onepill){document.querySelectorAll('[data-action="detail-tab"]').forEach(n=>n.classList.toggle('active',n.dataset.value===v));document.querySelector('#detail-data').innerHTML=detailBody(selectedCoin);document.querySelector('#onepill-market').dispatchEvent(new Event('onepill-tab'));if(v==='discussion')await loadThread(selectedCoin,routeEpoch,threadBefore)}else render()}else if(action==='copy'){await navigator.clipboard.writeText(v);toast('Copied.')}else if(action==='start-direct')await startDirect();else if(action==='continue-direct')await continueDirect();else if(action==='retry-direct')retryDirect();else if(action==='claim-position')await claimPosition(v);else if(action==='claim-social')await claimSocial(Number(v));else if(action==='propose-metadata')metadataDialog();else if(action==='submit-metadata')await submitMetadata();else if(action==='trade')await trade();else if(action==='sign-trade')await signTrade();else if(action==='refresh-trade'){modal.close();await trade();}else if(action==='link-x'){if(preview)return toast('X linking is unavailable in the design preview.');if(!wallet)return walletDialog();await ensureSession();const authConfig=await api.request('/auth/config');if(authConfig.privyAppId){const module=await import('./privy.js');const linked=await module.connectX(authConfig.privyAppId,api);toast('Connected @'+linked.username);return}const data=await api.linkX();const url=new URL(data.url);if(url.protocol!=='https:'||!['x.com','twitter.com'].includes(url.hostname))throw Error('Unexpected X authorization URL.');location.assign(url.href)}else if(action==='coin-submit-raid'){if(!wallet)return walletDialog();const url=new URL(document.querySelector('#coin-raid-url').value),match=url.pathname.match(/\/status\/(\d+)$/);if(url.protocol!=='https:'||!['x.com','www.x.com','twitter.com'].includes(url.hostname)||!match)throw Error('Enter a valid X post URL.');await ensureSession();await api.submitPost(selectedCoin.mint,match[1]);toast('Post submitted for verification.');}else if(action==='submit-post'){if(preview)return toast('Example mode does not submit posts.');if(!wallet)return walletDialog();const url=new URL(document.querySelector('#raid-url').value),match=url.pathname.match(/\/status\/(\d+)$/);if(!['x.com','www.x.com','twitter.com'].includes(url.hostname)||!match)throw Error('Enter a valid X post URL.');await ensureSession();await api.submitPost(document.querySelector('#raid-mint').value,match[1]);toast('Post submitted for verification.')}else if(action==='report'){showDialog('Report message',`<label class="field"><span>Reason</span><textarea id="report-reason" maxlength="500"></textarea></label><button class="primary wide" style="margin-top:15px" data-action="send-report" data-id="${e(button.dataset.id)}">Send report</button>`)}else if(action==='send-report'){await ensureSession();await api.report(Number(button.dataset.id),document.querySelector('#report-reason').value);modal.close();toast('Report submitted.')}else if(action==='risks')showDialog('Before you trade',`<p class="notice">This is an independent Solana launchpad, not affiliated with Fun or pump.fun. Only activated, indexed coins and finalized trades appear in the feed and charts.</p><p class="notice">Memecoins can lose their entire value. Wallet caps and launch protection do not eliminate market, smart-contract or counterparty risks. Real funding remains disabled pending deployment and validation.</p><p class="notice">Final terms and privacy disclosures must be published before a public launch.</p>`)}catch(err){toast(errorText(err))}});
document.addEventListener('keydown',evt=>{if((evt.metaKey||evt.ctrlKey)&&evt.key==='k'){evt.preventDefault();document.querySelector('#search')?.focus()}if(evt.key==='Escape')document.querySelector('#search-results')?.setAttribute('hidden','')});
let lastNavigationUrl='';
function handleNavigation(){if(location.hash)history.replaceState(history.state,'',routePath(publicRoute()));if(lastNavigationUrl===location.href)return;lastNavigationUrl=location.href;if(directBusy&&route()!=='status')directPaused=true;query='';detailTab='discussion';render();window.scrollTo(0,0)}
window.addEventListener('hashchange',handleNavigation);window.addEventListener('popstate',handleNavigation);
try{if(localStorage.getItem('mint-theme')==='light')document.body.classList.add('light');tradePending=!!sessionStorage.getItem('mint-pending-trade')}catch{}
render();if(!preview){loadCoins();loadHeaderActivity()}setInterval(loadHeaderActivity,2000);setInterval(()=>paintHeaderActivity(true),4000);pollTimer=setInterval(()=>{if(!document.hidden&&!preview&&!modal.open){if(route()==='home'&&!loading&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('#coin-grid:hover'))loadCoins();else if(route().startsWith('coin/')&&selectedCoin)loadDetail(selectedCoin,routeEpoch,true);else if(route()==='stats')loadStats(routeEpoch)}},2000);

async function loadRewards(c,epoch){
 const data=await api.proofs(c.mint,wallet);socialProofs=data.items??[];if(epoch!==routeEpoch)return;
 const area=document.querySelector('#rewards');if(!config.rpcUrl||!config.program||!config.genesis){area.innerHTML=empty('Reward plans',`${socialProofs.length} proof records found. On-chain verification will be available after deployment.`);return}
 const module=await import('./claims.js'),position=await module.positionStatus(config,c.mint,wallet);if(epoch!==routeEpoch)return;
 const states=await Promise.all(socialProofs.map(async p=>{try{return await module.socialClaimStatus(config,c.mint,wallet,p)}catch{return {claimable:false,label:'Could not verify round'}}}));if(epoch!==routeEpoch)return;
 area.innerHTML=`<div class="panel"><h3>Your position</h3><div class="receipt"><div><span>Program position</span><strong>${formatUnits(position.balance,6,6)} tokens</strong></div><div><span>Holder rewards</span><strong>${formatUnits(position.holderRewards,9,9)} SOL</strong></div></div><div class="row"><button data-action="claim-position" data-value="tokens" ${!position.canClaimTokens||!capabilities?.readyForFunds?'disabled':''}>Claim graduated tokens</button><button data-action="claim-position" data-value="holders" ${!position.canClaimRewards||!capabilities?.readyForFunds?'disabled':''}>Claim SOL rewards</button></div><p class="note">Verified at finalized slot ${position.slot}. Token claims respect developer locks.</p></div><h3 style="margin:24px 0 15px">YAP rounds</h3>${socialProofs.map((p,i)=>`<div class="panel row between" style="margin-bottom:10px"><div><strong>${formatUnits(p.amount,9,9)} SOL</strong><p class="note">${e(states[i].label)}</p></div><button data-action="claim-social" data-value="${i}" ${!states[i].claimable||!capabilities?.readyForFunds?'disabled':''}>Review claim</button></div>`).join('')||empty('No YAP rewards yet','Eligible, funded rounds will appear here.')}`;
}
function reviewAction(prepared,title){preparedTrade=prepared;showDialog(title,`<p class="notice">Review the action and approve it in your wallet. A network fee applies.</p><div class="receipt">${Object.entries(prepared.quote).map(([key,value])=>`<div><span>${e(key)}</span><span style="overflow-wrap:anywhere;max-width:65%">${e(value)}</span></div>`).join('')}</div><button class="primary wide" data-action="sign-trade">Approve in wallet</button><div class="error" id="trade-error"></div>`)}
async function claimPosition(kind){if(!wallet)return walletDialog();if(!capabilities?.readyForFunds||tradePending)throw Error('Claims are not available while the deployment or a transaction is pending.');const module=await import('./claims.js');reviewAction(await module.preparePositionClaim(config,selectedCoin.mint,wallet,kind),'Review your claim')}
async function claimSocial(index){if(!wallet)return walletDialog();if(!capabilities?.readyForFunds||tradePending)throw Error('Claims are not available while the deployment or a transaction is pending.');const module=await import('./claims.js');reviewAction(await module.prepareSocialClaim(config,selectedCoin.mint,wallet,socialProofs[index]),'Review YAP reward')}
function metadataDialog(){if(!wallet)return walletDialog();showDialog('Suggest an update',`<div class="stack"><label class="field"><span>Proposed name</span><input id="proposal-name" maxlength="32" value="${e(selectedCoin.name)}"></label><label class="field"><span>Published metadata URI</span><input id="proposal-uri" placeholder="https://…/metadata.json"></label><p class="note">You must hold this coin. The moderator can select a proposal after 24 hours. This does not change the ticker or fee rules.</p><button class="primary" data-action="submit-metadata" ${!capabilities?.readyForFunds?'disabled':''}>Review proposal</button></div>`)}
async function submitMetadata(){if(!capabilities?.readyForFunds||tradePending)throw Error('Metadata proposals are not enabled yet.');const module=await import('./claims.js');reviewAction(await module.prepareMetadataProposal(config,selectedCoin.mint,wallet,{name:document.querySelector('#proposal-name').value,uri:document.querySelector('#proposal-uri').value}),'Review proposal')}

async function ensureSession(){if(!provider||!wallet)throw Error('Connect your wallet first.');if(!authenticated){const module=await import('./wallet.js');const signedWallet=await module.authenticate(provider,api);if(signedWallet!==wallet)throw Error('Wallet changed. Reconnect and try again.');authenticated=true}}
function readDirect(){try{return JSON.parse(localStorage.getItem('mint-direct-launch')||'null')}catch{return null}}
function persistDirect(record){localStorage.setItem('mint-direct-launch',JSON.stringify(record))}
async function startDirect(){if(!pendingDirect||!capabilities?.readyForFunds||!config.directLaunchEnabled)throw Error('Direct launches are not enabled yet.');const old=readDirect();if(old&&old.step<old.stageCount&&(old.pending||old.history.length))throw Error('Finish the existing launch before starting another.');persistDirect(pendingDirect);modal.close();location.hash='status';await continueDirect()}
async function continueDirect(){
 if(directBusy)return;if(!wallet)return walletDialog();const record=readDirect();if(!record)return;
 if(record.owner!==wallet)throw Error('Connect the wallet that started this launch.');
 directBusy=true;directPaused=false;directMessage='Preparing your next wallet confirmation…';render();
 try{if(record.route==='native-pump')await ensureSession();const module=await import(record.route==='native-pump'?'./native-pump.js':'./direct-launch.js');
 if(module.launchStageKinds){record.stageKinds=module.launchStageKinds(record);persistDirect(record)}else if(!record.stageKinds){record.stageKinds=Array.from({length:record.stageCount},(_,i)=>i===0?'create_launch':'execute_developer_buy');persistDirect(record)}
 const result=await runLaunchFlow({record,canContinue:()=>!directPaused&&route()==='status'&&wallet===record.owner,
 advance:()=>module.advanceDirectLaunch(config,record,provider,persistDirect,progress=>{directMessage=progress.state==='wallet'?'Approve “'+(launchStepNames[progress.kind]||'launch')+'” in your wallet. If it did not open, open your wallet extension.':'Transaction sent. Waiting for confirmation—do not submit it again.';if(route()==='status')render()}),
 reconcile:()=>module.reconcileDirectLaunch(config,record,wallet,persistDirect),
 onUpdate:result=>{directMessage=result.waiting||'Preparing the next step…';if(route()==='status')render()}});
 if(result.done&&route()==='status'){
  for(let attempt=0;attempt<24&&route()==='status'&&!directPaused;attempt++){
   await loadCoins();const launched=coins.find(c=>c.mint===record.mint&&['curve','pumpswap'].includes(c.phase));
   if(launched){directMessage='Launched!';toast('Launched!');location.hash='coin/'+(launched.launch||launched.id);break}
   const note=document.querySelector('#direct-status-note');if(note)note.textContent='Launch confirmed. Preparing your coin page…';
   await new Promise(resolve=>setTimeout(resolve,2500));
  }
 }
 directBusy=false;directMessage=result.waiting||(result.paused?'Paused. Your completed steps are saved.':result.done?'Launch confirmed. Your coin page is being indexed.':'');if(route()==='status')render();
 }catch(error){directBusy=false;directMessage=errorText(error)+' Your completed steps are saved. Click Continue when ready.';toast(errorText(error));if(route()==='status')render()}finally{directBusy=false}
}

function retryDirect(){const record=readDirect();if(!record||record.pending||record.history.at(-1)?.state!=='failed')throw Error('Only a definitively failed transaction can be retried.');record.failure=null;persistDirect(record);render()}

async function loadCoinRoute(id,epoch){try{if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(id))throw Error('Invalid coin address.');let data;try{data=await api.coin(id)}catch(error){const found=await api.request('/coins/board?limit=48&search='+encodeURIComponent(id));const coin=found.coins.find(c=>c.mint===id);if(!coin)throw error;data={coin}}if(epoch!==routeEpoch)return;if(data.coin.onepill){const c={...data.coin,id:data.coin.launch||data.coin.id};coins.push(c);rememberCoinRoute(c);await loadOnepill(c.id,epoch);return;}if(!['curve','pumpswap'].includes(data.coin.phase))throw Error('This coin has not activated.');coins.push({...data.coin,id:data.coin.launch,example:false});render()}catch(error){if(epoch===routeEpoch)shell(empty('Coin unavailable',errorText(error),'<a href="#home" class="btn">Back to coins</a>'))}}

async function publishDraftMetadata(){
 if(!imageFile)return;
 const key=JSON.stringify([draft.name,draft.ticker,draft.description,draft.twitter,draft.telegram,draft.website,imageFile.name,imageFile.size,imageFile.lastModified]);
 if(uploadedMetadataKey===key&&draft.uri)return;
 await ensureSession();
 const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read your picture.'));reader.readAsDataURL(imageFile)});
 const result=await api.request('/media',{method:'POST',body:{name:draft.name,symbol:draft.ticker,description:draft.description,twitter:draft.twitter,telegram:draft.telegram,website:draft.website,image}});
 draft.uri=result.uri;uploadedMetadataKey=key;
}

async function loadThread(c,epoch,before=null){
 if(threadMint!==c.mint){threadMint=c.mint;threadBefore=null;threadPages=[];before=null}
 const data=await api.discussions(c.mint,before);if(epoch!==routeEpoch)return;for(const p of data.posts){const key=wallet+':'+p.id;p.liked?likedPosts.add(key):likedPosts.delete(key)}
 document.querySelector('#posts').innerHTML=data.posts.map(p=>`<article class="panel thread-post" id="reply-${p.id}"><div class="thread-reply-meta">${walletBadge(p.wallet,p.wallet===c.creator)}<time datetime="${new Date(p.created*1000).toISOString()}">${e(new Date(p.created*1000).toLocaleString())}</time></div><p>${e(p.text)}</p>${p.image&&/^\/media\/[a-f0-9]{64}\.webp$/.test(p.image)?`<a href="${e(p.image)}" target="_blank" rel="noopener noreferrer"><img src="${e(p.image)}" alt="Reply attachment" loading="lazy" style="max-width:100%;max-height:320px;object-fit:contain"></a>`:''}<div class="row" style="gap:16px"><button data-action="like-comment" data-value="${p.id}" aria-pressed="${likedPosts.has(wallet+':'+p.id)}">♥ ${p.likes??0}</button><button class="subtle" data-action="report" data-id="${p.id}">Report</button></div></article>`).join('');
 if(!before)document.querySelector('#posts').insertAdjacentHTML('afterbegin',`<article class="thread-opening thread-post"><div>${walletBadge(c.creator,true)} <time>${c.createdAt?e(new Date(c.createdAt*1000).toLocaleString()):''}</time></div><div class="thread-coin-intro"><img src="${art(c)}" alt="${e(c.name)}"><div><strong>${e(c.name)} (ticker: ${e(c.symbol)})</strong><p>${e(c.description||'')}</p></div></div></article>`);
 if(threadPages.length||data.next)document.querySelector('#posts').insertAdjacentHTML('beforeend',`<nav class="thread-pagination" aria-label="Thread pages">${threadPages.map((_,i)=>`<button data-action="thread-page" data-value="${i}" aria-label="Thread page ${i+1}">${i+1}</button>`).join('')}<span aria-current="page">${threadPages.length+1}</span>${data.next?`<button data-action="thread-next" data-value="${data.next}" aria-label="Thread page ${threadPages.length+2}">${threadPages.length+2}</button>`:''}</nav>`);
}

async function loadTrades(c,epoch,cursor=null){
 if(tradeCoin!==c.id){tradeCoin=c.id;tradeCursor=null;tradePages=[];cursor=null}
 const request=++tradesRequest;const data=await api.trades(c.id,cursor);if(epoch!==routeEpoch||request!==tradesRequest||detailTab!=='activity')return;
 document.querySelector('#activity').innerHTML=`<div class="trade-table-wrap"><table class="classic-trades"><thead><tr><th>account</th><th>type</th><th>SOL</th><th>${e(c.symbol||'tokens')}</th><th>date</th><th>transaction</th></tr></thead><tbody>${data.trades.map(t=>`<tr><td>${walletBadge(t.trader,t.trader===c.creator)}</td><td class="${t.buy?'trade-buy':'trade-sell'}">${t.buy?'buy':'sell'}</td><td>${formatUnits(t.quote,9,6)}</td><td>${formatUnits(t.base,6,2)}</td><td>${t.time==null?'slot '+e(t.slot):e(new Date(t.time*1000).toLocaleString())}</td><td><a href="https://solscan.io/tx/${e(t.signature)}" target="_blank" rel="noopener noreferrer">${e(short(t.signature))}</a></td></tr>`).join('')}</tbody></table></div>${data.trades.length?'':empty('No finalized trades yet','Confirmed buys and sells appear here.')}${tradePages.length||data.nextCursor?`<nav class="thread-pagination trades-pagination" aria-label="Trade pages">${tradePages.map((_,i)=>`<button data-action="trades-page" data-value="${i}" aria-label="Trade page ${i+1}">${i+1}</button>`).join('')}<span aria-current="page">${tradePages.length+1}</span>${data.nextCursor?`<button data-action="trades-next" data-value="${e(data.nextCursor)}" aria-label="Trade page ${tradePages.length+2}">${tradePages.length+2}</button>`:''}</nav>`:''}`;
}

async function loadHolders(c,epoch){try{const data=await getHolders(c);if(epoch!==routeEpoch)return;document.querySelector('#holder-distribution').innerHTML=`<h2>Holder distribution</h2><ol class="holder-list">${data.holders.map(h=>`<li>${h.role==='bonding curve'?`<a href="https://solscan.io/account/${e(h.account)}">${e(walletName(h.wallet))} (bonding curve)</a>`:walletBadge(h.wallet,h.role==='dev')}<span>${(h.supplyBps/100).toFixed(2)}%</span></li>`).join('')}</ol><small>${data.holders.length?(data.partial?'Known traders · partial coverage':'Largest '+(data.scope==='largest_program_positions'?'program positions':'token accounts')):'No holders'} · finalized slot ${e(data.slot)}</small>`}catch(error){if(epoch===routeEpoch)document.querySelector('#holder-distribution').innerHTML='<h2>Holder distribution</h2><p class="note">'+e(errorText(error))+'</p>'}}

let profileData=null,profileTab='held',profilePage=0,profileRenderId=0;
function walletAvatar(address){queueWalletProfiles();return `<img class="wallet-avatar" data-wallet-avatar="${e(address)}" src="${e(walletAvatars.get(address)||'/assets/default-pepe.png')}" alt="Profile avatar" width="16" height="16">`}
function rememberWalletProfile(p){if(p.username)walletNames.set(p.wallet,p.username);else walletNames.delete(p.wallet);if(p.avatar&&/^\/media\/[a-f0-9]{64}\.webp$/.test(p.avatar))walletAvatars.set(p.wallet,p.avatar);else walletAvatars.delete(p.wallet);walletProfileTimes.set(p.wallet,Date.now());if(walletProfileTimes.size>1000){const first=walletProfileTimes.keys().next().value;walletProfileTimes.delete(first);walletNames.delete(first);walletAvatars.delete(first)}}
function queueWalletProfiles(){if(!walletHydrationTimer)walletHydrationTimer=setTimeout(()=>{walletHydrationTimer=null;hydrateWalletProfiles()},100)}
async function hydrateWalletProfiles(){if(walletHydrationBusy||preview)return;walletHydrationBusy=true;try{const addresses=[...new Set([...document.querySelectorAll('[data-wallet-avatar]')].map(el=>el.dataset.walletAvatar))].filter(a=>!walletProfileTimes.has(a)||Date.now()-walletProfileTimes.get(a)>30000);for(let i=0;i<addresses.length;i+=30){const data=await api.request('/profiles/public?wallets='+encodeURIComponent(addresses.slice(i,i+30).join(',')));for(const p of data.profiles)rememberWalletProfile(p)}for(const el of document.querySelectorAll('[data-wallet-name]'))el.textContent=(walletNames.get(el.dataset.walletName)||el.dataset.walletName.slice(0,6))+(el.dataset.walletDev==='true'?' (dev)':'');for(const el of document.querySelectorAll('[data-wallet-avatar]')){const src=walletAvatars.get(el.dataset.walletAvatar)||'/assets/default-pepe.png';if(el.getAttribute('src')!==src)el.src=src}}catch{/* Preserve the address fallback if public profiles are temporarily unavailable. */}finally{walletHydrationBusy=false}}
async function editOwnProfile(){if(!wallet)return walletDialog();if(profileData?.wallet!==wallet)return;await ensureSession();showDialog('Edit profile',`<form id="profile-edit-form" class="stack"><div class="profile-edit-avatar">${walletAvatar(wallet)}</div><label class="field"><span>Username</span><input name="username" required minlength="1" maxlength="20" pattern="[A-Za-z0-9_]{1,20}" value="${e(profileData.username||wallet.slice(0,6))}" autocomplete="off"><small>1–20 characters · letters, numbers and underscores.</small></label><label class="field"><span>Profile image</span><input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP · up to 4 MB.</small></label><label class="profile-reset"><input name="resetAvatar" type="checkbox"> Use the default Pepe image</label><p id="profile-save-error" class="error" role="alert"></p><button type="submit" class="primary">Save profile</button></form>`);document.querySelector('#profile-edit-form').addEventListener('submit',saveOwnProfile)}
async function saveOwnProfile(event){event.preventDefault();if(profileSaveBusy)return;profileSaveBusy=true;const form=event.currentTarget,submit=form.querySelector('[type=submit]'),error=form.querySelector('#profile-save-error');submit.disabled=true;error.textContent='';const editingWallet=wallet;try{await ensureSession();const fields=new FormData(form),username=String(fields.get('username')||'').trim();if(!/^[A-Za-z0-9_]{1,20}$/.test(username))throw Error('Use 1–20 letters, numbers or underscores.');let avatar=fields.get('resetAvatar')?null:profileData.avatar;const file=fields.get('avatar');if(file?.size&&!fields.get('resetAvatar')){if(file.size>4*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPG or WebP under 4 MB.');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const upload=await api.request('/media',{method:'POST',body:{name:'Profile image',symbol:'AVATAR',description:'',image}});avatar=new URL(upload.image).pathname}if(wallet!==editingWallet)throw Error('Wallet changed. Reopen the profile editor.');const result=await api.request('/profiles',{method:'POST',body:{username,avatar:avatar??null,wallet:editingWallet}});rememberWalletProfile(result);modal.close();toast('Profile saved.');render()}catch(err){const messages={profile_name_taken:'That username is already taken.',profile_name_invalid:'Use 1–20 letters, numbers or underscores.',profile_update_rate_limit:'Wait 10 seconds before saving again.'};error.textContent=messages[err.message]||errorText(err)}finally{profileSaveBusy=false;submit.disabled=false}}

async function loadProfile(address,epoch){try{const data=await api.request('/profiles?wallet='+encodeURIComponent(address));if(epoch!==routeEpoch)return;if(profileData?.wallet!==data.wallet){profileTab='held';profilePage=0}rememberWalletProfile(data);profileData=data;renderProfile(epoch)}catch(error){if(epoch===routeEpoch)shell(empty('Profile unavailable',errorText(error)))}}
function renderProfile(epoch){const data=profileData;if(!data)return;const tabs=[['held','coins held'],['created','coins created'],...(data.ownReplies?[['replies','replies']]:[])];if(!tabs.some(([id])=>id===profileTab))profileTab='held';shell(`<div class="classic-profile"><header class="profile-identity">${walletAvatar(data.wallet)}<h1 data-wallet-name="${e(data.wallet)}">${e(walletName(data.wallet))}</h1><div class="profile-wallet"><button class="subtle" data-action="copy" data-value="${e(data.wallet)}" title="${e(data.wallet)}">${e(short(data.wallet))} ${icon('copy')}</button><a href="https://solscan.io/account/${e(data.wallet)}" target="_blank" rel="noopener noreferrer">[view on solscan]</a></div>${data.wallet===wallet?'<button class="subtle" data-action="edit-profile">[edit profile]</button>':''}${data.wallet===wallet&&!data.ownReplies?'<button class="subtle" data-action="profile-auth">[sign in to view your replies]</button>':''}</header><nav class="profile-tabs" aria-label="Wallet profile">${tabs.map(([id,label])=>`<button data-action="profile-tab" data-value="${id}" class="${profileTab===id?'active':''}" aria-pressed="${profileTab===id}">${label}</button>`).join('')}</nav><div id="profile-content"></div></div>`);loadProfileContent(epoch)}
async function loadProfileContent(epoch){const data=profileData,id=++profileRenderId,tab=profileTab,items=tab==='created'?data.created:tab==='replies'?data.replies:data.held??[],page=items.slice(profilePage*12,(profilePage+1)*12),el=document.querySelector('#profile-content');if(tab==='held'&&data.holdingsError){el.innerHTML=`<p class="profile-empty">${e(data.holdingsError)}</p>`;return}if(!page.length){el.innerHTML=`<p class="profile-empty">${tab==='held'?'No Pill coins held.':tab==='created'?'No coins created yet.':'No replies yet.'}</p>`;return}const controls=()=>`<div class="profile-pagination"><button data-action="profile-page" data-value="${profilePage-1}" ${profilePage?'':'disabled'}>[ &lt;&lt; ]</button><span>${profilePage+1} / ${Math.ceil(items.length/12)}</span><button data-action="profile-page" data-value="${profilePage+1}" ${(profilePage+1)*12<items.length?'':'disabled'}>[ &gt;&gt; ]</button></div>`;if(tab==='replies'){el.innerHTML=page.map(reply=>`<article class="profile-reply"><a href="#coin/${e(reply.launch)}">${e(reply.symbol||short(reply.mint))}</a><time>${e(new Date(reply.created*1000).toLocaleString())}</time><p>${e(reply.text)}</p></article>`).join('')+controls();return}el.innerHTML='<p class="profile-empty">Loading coin details…</p>';let quote=null;try{quote=await getDollarQuote()}catch{}const enriched=[];for(let i=0;i<page.length;i+=4){enriched.push(...await Promise.all(page.slice(i,i+4).map(async coin=>{try{const detail=await api.coin(coin.launch);let supply=null;if(tab==='held'){try{supply=(await getHolders({...detail.coin,id:coin.launch})).totalSupplyRaw}catch{}}return {...coin,...detail.coin,balanceRaw:coin.balanceRaw,totalSupplyRaw:supply}}catch{return coin}})));if(epoch!==routeEpoch||id!==profileRenderId)return}if(epoch!==routeEpoch||id!==profileRenderId||!el.isConnected)return;el.innerHTML=enriched.map(coin=>{const cap=Number(coin.cap),usd=quote?.expiresAt>Date.now()&&cap>0?compactUsd(cap*quote.price):'—';return `<article class="profile-coin"><a href="#coin/${e(coin.launch)}" class="profile-coin-art"><img src="${art(coin)}" alt="${e(coin.name||coin.symbol)}" loading="lazy"></a><div><div class="author">created by ${walletBadge(coin.creator)} <span class="tag">${coin.version===2?'New School · Holder Rewards':coin.version===11?'Stealth V1.1':'Stealth Classic V1'}</span></div><div class="classic-cap">market cap: ${usd}</div><div class="classic-replies">replies: ${Number.isInteger(coin.replyCount)?coin.replyCount:'—'}</div><a class="profile-coin-name" href="#coin/${e(coin.launch)}">${crownBadge(coin)}${e(coin.name||short(coin.mint))} (ticker: ${e(coin.symbol||'—')})</a>${tab==='held'?`<p class="profile-balance">held: ${supplyPercentage(coin.balanceRaw,coin.totalSupplyRaw)} of supply</p>`:''}${coin.description?`<p class="profile-description">${e(coin.description)}</p>`:''}</div></article>`}).join('')+controls()}


function placeTradePanel(){const side=document.querySelector('.coin-detail-side');if(side)for(const id of ['coin-trade-panel','coin-about','curve-detail','crown-status','holder-distribution']){const el=document.getElementById(id);if(el)side.append(el)}}

function observeProvider(p){if(p.__pillObserved)return;p.__pillObserved=true;p.on?.('accountChanged',key=>{wallet=key?.toString()??'';draft.wallet=wallet;authenticated=false;render()});p.on?.('disconnect',()=>{wallet='';authenticated=false;render()})}
async function restoreWallet(){try{const name=localStorage.getItem('pill-wallet-provider');if(!name)return;const {availableWallets}=await import('./wallet.js');const match=availableWallets().find(([n])=>n===name);if(!match)return;const p=match[1],result=await p.connect({onlyIfTrusted:true});if(!result?.publicKey&&!p.publicKey)return;provider=p;wallet=(result.publicKey??p.publicKey).toString();draft.wallet=wallet;authenticated=false;observeProvider(p);render()}catch{}}
if(!preview)restoreWallet();

async function getDollarQuote(){if(!dollarQuote||Date.now()-dollarQuote.fetchedAt>10000){dollarRequest??=api.request('/quotes/sol-usd').finally(()=>dollarRequest=null);dollarQuote={...await dollarRequest,fetchedAt:Date.now()}}return dollarQuote}

async function getHolders(c){if(c.holderSnapshot&&Date.now()-c.holderFetchedAt<10000)return c.holderSnapshot;if(c.holderRequest)return c.holderRequest;c.holderRequest=api.request('/holders?mint='+encodeURIComponent(c.mint)).then(data=>{c.holderSnapshot=data;c.holderFetchedAt=Date.now();return data}).finally(()=>c.holderRequest=null);return c.holderRequest}

document.addEventListener("change",event=>{if(event.target.id==="chart-timeframe"){const value=Number(event.target.value);if([60,300,900,3600,14400,86400].includes(value)){interval=value;render()}}});

document.addEventListener("change",event=>{if(event.target.dataset.indicator)setChartIndicator(event.target.dataset.indicator,event.target.checked)});

let pendingRecoveryBusy=false;
async function recoverPendingTrade(){if(pendingRecoveryBusy||!tradePending)return;pendingRecoveryBusy=true;try{const record=JSON.parse(sessionStorage.getItem('mint-pending-trade')||'null');if(!record){tradePending=false;return}const {reconcilePendingTrade}=await import('./wallet.js');const result=await reconcilePendingTrade(config,record);if(['finalized','failed','expired'].includes(result.state)){sessionStorage.removeItem('mint-pending-trade');tradePending=false;const message=result.state==='finalized'?'Your previous transaction finalized.':result.state==='failed'?'Your previous transaction failed. You can request a new quote.':'Your previous transaction expired without confirming. You can request a new quote.';toast(message);const el=document.querySelector('#trade-error');if(el)el.textContent=message;const button=modal.querySelector('[data-action=sign-trade]');if(button){button.disabled=false;button.dataset.action='refresh-trade';button.textContent='Get a fresh quote'}}}catch{/* Keep uncertain signatures blocked until RPC can confirm their outcome. */}finally{pendingRecoveryBusy=false}}
setInterval(()=>{if(!document.hidden&&tradePending)recoverPendingTrade()},10000);
if(tradePending)recoverPendingTrade();

document.addEventListener('change',event=>{if(event.target.matches('[data-chart-setting]'))chartDisplay(event.target.dataset.chartSetting,event.target.checked);if(event.target.id==='chart-date')chartDate(event.target.value)});
setInterval(()=>{const clock=document.querySelector('#chart-clock');if(clock)clock.textContent=new Date().toISOString().slice(11,19)+' (UTC)'},1000);

function docs(){return `<article class="classic-mission"><h1>Pill launch guide</h1><p>Old School, New School and onepill mode use different contracts. Read each route’s fees, trading rules and launch steps.</p><iframe title="Pill launch documentation" src="/docs.html" style="width:100%;height:75vh;border:0"></iframe></article>`}

async function loadOnepill(id,epoch){try{const data=await api.request('/launch/onepill/status?id='+encodeURIComponent(id));if(epoch!==routeEpoch)return;if(data.state!=='done'){shell(onepillStatus(data));setTimeout(()=>{if(epoch===routeEpoch&&!document.hidden)loadOnepill(id,epoch)},12000);return}const c={...data,mint:data.chains.solana.token,id,phase:'onepill',createdAt:data.created,chartInterval:interval};rememberCoinRoute(c);shell(detail(c));placeTradePanel();document.querySelector('.detail-layout').id='onepill-market';document.querySelector('#coin-trade-panel').outerHTML=solanaTradeForm(c);document.querySelector('#curve-detail').innerHTML=`<details class="onepill-addresses" open><summary>Five chain contracts</summary>${Object.entries(c.chains).map(([chain,row])=>`<div class="onepill-chain-address"><strong>${e(chain)}</strong><button data-action="copy" data-value="${e(row.token)}" title="Copy ${e(chain)} contract">${e(short(row.token))} ${icon('copy')}</button></div>`).join('')}</details><p class="note">Trading here uses the Solana pool. Powered by <a href="https://www.pangea.trade" target="_blank" rel="noopener noreferrer">Pangea</a>.</p>`;disposeOnepillMarket?.();disposeOnepillMarket=mountOnepillMarket(c,{api,config,getProvider:()=>provider,connectWallet:walletDialog,walletBadge,onCrown:x=>{Object.assign(c,{kingOfTheHill:x.kingOfTheHill});const el=document.querySelector('#crown-status');if(el)el.innerHTML=crownPanel(c)}});loadHolders(c,epoch);if(detailTab==='discussion')loadThread(c,epoch,threadBefore).catch(error=>{if(epoch===routeEpoch)document.querySelector('#posts').textContent=errorText(error)});}catch(error){if(epoch===routeEpoch)shell(empty('OnePill unavailable',errorText(error)))}}

function bindOnepill(){document.querySelector('#onepill-form')?.addEventListener('input',event=>{sessionStorage.setItem('pill-onepill-draft',JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))))});document.querySelector('#onepill-form')?.addEventListener('submit',async event=>{event.preventDefault();if(onepillActionBusy)return;onepillActionBusy=true;const form=new FormData(event.target),button=event.submitter;button.disabled=true;try{await ensureSession();onepillReview=await quoteOnepill(api,form,wallet);showDialog('Review OnePill launch',reviewOnepill(onepillReview))}catch(error){const el=document.querySelector('#onepill-feedback');if(el)el.textContent=errorText(error);else toast(errorText(error))}finally{onepillActionBusy=false;button.disabled=false;}})}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-onepill]');if(!button||onepillActionBusy)return;onepillActionBusy=true;button.disabled=true;try{const action=button.dataset.onepill;if(action==='connect'){const address=await connectEvm();button.textContent=short(address)}else if(action==='pay'){await ensureSession();await payOnepill(api,onepillReview,provider);modal.close();location.hash='onepill/'+onepillReview.id;toast('Payment sent. Pangea will verify it and launch on each chain.')}else if(action==='mine'){await ensureSession();const data=await api.request('/launch/onepill/mine');showDialog('My OnePill launches',data.launches.map(c=>`<div class="data-row"><a href="#onepill/${e(c.id)}" data-action="close">${e(c.name)} · ${e(c.state)}</a>${c.state==='quoted'?`<button data-onepill="review" data-id="${e(c.id)}">Review quote</button>`:''}</div>`).join('')||'<p>No OnePill launches yet.</p>')}else if(action==='review'){await ensureSession();const data=await api.request('/launch/onepill/mine');onepillReview=data.launches.find(c=>c.id===button.dataset.id);if(!onepillReview)throw Error('Launch not found.');showDialog('Review OnePill launch',reviewOnepill(onepillReview))}else if(action==='resume'){await ensureSession();await resumeOnepill(api,button.dataset.id);render()}}catch(error){const el=document.querySelector('#onepill-feedback');if(el)el.textContent=errorText(error);else toast(errorText(error))}finally{onepillActionBusy=false;button.disabled=false;}});

function launchSchools(){const native=draft.school==='new',onepill=draft.school==='onepill';
 return `<section class="launch-schools" aria-label="Launch routes"><section class="panel"><span class="tag">Old School</span><h2>Start on Pill. Graduate to PumpSwap.</h2><p class="panel-description">Choose Stealth Classic V1 or Stealth V1.1. Trade on Pill’s custom curve before graduation; the launch contract burns its received PumpSwap LP tokens at migration.</p><button type="button" data-action="option" data-name="school" data-value="old" aria-pressed="${!native&&!onepill}">${!native&&!onepill?'Old School selected':'Choose Old School'}</button><div class="launch-route-footer"><p class="note provider-attribution">Powered by <a class="pangea-brand" href="https://swap.pump.fun" target="_blank" rel="noopener noreferrer"><img src="/assets/pump-fun.png" width="18" height="18" alt=""><span class="provider-beta">beta</span>PumpSwap</a></p><aside class="developer-lock-warning stealth-notice" role="note"><strong>STEALTH FOR A REASON</strong><p>Built for everyday traders who want to get in early, before migration. Connect your wallet, trade here on Pill and enjoy the journey with the community.</p><p>At graduation, liquidity moves to PumpSwap and the received LP tokens are burned, opening trading to a wider audience, just like the old days.</p></aside></div></section><section class="panel"><span class="tag">New School</span><h2>Native Pump Holder Rewards</h2><p class="panel-description">Launch through Pump’s real contract and follow the coin on Pill. Creator fees go to holders through Pump’s reward distribution. No cashback or regular Pump launches are substituted.</p><button type="button" data-action="option" data-name="school" data-value="new" aria-pressed="${native}">${native?'New School selected':'Choose New School'}</button><div class="launch-route-footer"><p class="note provider-attribution">Powered by <a class="pangea-brand" href="https://pump.fun" target="_blank" rel="noopener noreferrer"><img src="/assets/pump-fun.png" width="18" height="18" alt="">pump.fun</a></p><aside class="developer-lock-warning stealth-notice" role="note"><strong>REWARDS FOR HOLDERS</strong><p>Launch on Pump.fun with Holder Rewards enabled. Creator fees go to eligible holders through Pump’s native reward distribution.</p><p>Follow your coin here on Pill while it trades through Pump’s ecosystem. This route uses Pump’s launch rules and fees.</p></aside></div><\/section><section class="panel"><span class="tag onepill-tag">onepill mode</span><h2>One coin. Five chains.</h2><p class="panel-description">Launch one coin with the same name and ticker across Ethereum, Base, BNB Chain, Robinhood Chain and Solana. One launch, five chains. Fixed 1% trading fee.</p><button type="button" data-action="option" data-name="school" data-value="onepill" aria-pressed="${onepill}">${onepill?'onepill mode selected':'Choose onepill mode'}</button><div class="launch-route-footer"><p class="note provider-attribution">Powered by <a class="pangea-brand" href="https://www.pangea.trade" target="_blank" rel="noopener noreferrer"><img src="/assets/pangea-mark.svg" width="18" height="18" alt="">Pangea</a></p><aside class="developer-lock-warning stealth-notice" role="note"><strong>ONE LAUNCH, FIVE COMMUNITIES</strong><p>Bring the same coin name, ticker and identity to five chains through Pangea. Give each community a way to join on its preferred chain.</p><p>Create your launch here on Pill with a fixed 1% trading fee, then follow the progress of each chain in one place.</p></aside></div></section></section>`;
}

// Refresh active market data without repeating slower wallet/rules requests.
let fastMarketBusy=false;
setInterval(async()=>{if(fastMarketBusy||document.hidden||preview||!route().startsWith("coin/")||!selectedCoin)return;fastMarketBusy=true;const coin=selectedCoin,epoch=routeEpoch;try{await Promise.allSettled([loadCandles(coin,epoch),...(detailTab==="activity"&&!tradeCursor?[loadTrades(coin,epoch,null)]:[])])}finally{fastMarketBusy=false}},1000);
